/* DAWAH X — ahmad, অধ্যায় 107 · খণ্ড 107 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][107]=[[21201,21201,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَبِي غَالِبٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏أَبَا أُمَامَةَ ‏ ‏عَنْ ‏ ‏النَّافِلَةِ ‏ ‏فَقَالَ ‏ ‏كَانَتْ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَافِلَةً ‏ ‏وَلَكُمْ فَضِيلَةً ‏","","",""],[21202,21202,"","","‏ ‏حَدَّثَنَا ‏ ‏سَيَّارُ بْنُ حَاتِمٍ ‏ ‏حَدَّثَنَا ‏ ‏جَعْفَرٌ ‏ ‏قَالَ ‏ ‏أَتَيْتُ ‏ ‏فَرْقَدًا ‏ ‏يَوْمًا فَوَجَدْتُهُ خَالِيًا فَقُلْتُ يَا ‏ ‏ابْنَ أُمِّ فَرْقَدٍ ‏ ‏لَأَسْأَلَنَّكَ الْيَوْمَ عَنْ هَذَا الْحَدِيثِ فَقُلْتُ أَخْبِرْنِي عَنْ قَوْلِكَ فِي ‏ ‏الْخَسْفِ ‏ ‏وَالْقَذْفِ أَشَيْءٌ تَقُولُهُ أَنْتَ أَوْ تَأْثُرُهُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَا بَلْ آثُرُهُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْتُ وَمَنْ حَدَّثَكَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَاصِمُ بْنُ عَمْرٍو الْبَجَلِيُّ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَحَدَّثَنِي ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ الْمُسَيَّبِ ‏ ‏وَحَدَّثَنِي ‏ ‏بِهِ ‏ ‏إِبْرَاهِيمُ النَّخَعِيُّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَبِيتُ طَائِفَةٌ مِنْ أُمَّتِي عَلَى أَكْلٍ وَشُرْبٍ وَلَهْوٍ وَلَعِبٍ ثُمَّ يُصْبِحُونَ قِرَدَةً وَخَنَازِيرَ فَيُبْعَثُ عَلَى أَحْيَاءٍ مِنْ أَحْيَائِهِمْ رِيحٌ فَتَنْسِفُهُمْ كَمَا نَسَفَتْ مَنْ كَانَ قَبْلَهُمْ بِاسْتِحْلَالِهِمْ الْخُمُورَ وَضَرْبِهِمْ بِالدُّفُوفِ وَاتِّخَاذِهِمْ ‏ ‏الْقَيْنَاتِ ‏","","",""],[21203,21203,"","","‏ ‏حَدَّثَنَا ‏ ‏الْهُذَيْلُ بْنُ مَيْمُونٍ الْكُوفِيُّ الْجُعْفِيُّ ‏ ‏كَانَ يَجْلِسُ فِي مَسْجِدِ ‏ ‏الْمَدِينَةِ ‏ ‏يَعْنِي مَدِينَةَ ‏ ‏أَبِي جَعْفَرٍ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏هَذَا شَيْخٌ قَدِيمٌ كُوفِيٌّ ‏ ‏عَنْ ‏ ‏مُطَّرِحِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ زَحْرٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ يَزِيدَ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلْتُ الْجَنَّةَ فَسَمِعْتُ فِيهَا ‏ ‏خَشْفَةً ‏ ‏بَيْنَ يَدَيَّ فَقُلْتُ مَا هَذَا قَالَ ‏ ‏بِلَالٌ ‏ ‏قَالَ فَمَضَيْتُ فَإِذَا أَكْثَرُ أَهْلِ الْجَنَّةِ فُقَرَاءُ ‏ ‏الْمُهَاجِرِينَ ‏ ‏وَذَرَارِيُّ ‏ ‏الْمُسْلِمِينَ وَلَمْ أَرَ أَحَدًا أَقَلَّ مِنْ الْأَغْنِيَاءِ وَالنِّسَاءِ قِيلَ لِي أَمَّا الْأَغْنِيَاءُ فَهُمْ هَاهُنَا بِالْبَابِ يُحَاسَبُونَ ‏ ‏وَيُمَحَّصُونَ ‏ ‏وَأَمَّا النِّسَاءُ فَأَلْهَاهُنَّ الْأَحْمَرَانِ الذَّهَبُ وَالْحَرِيرُ قَالَ ثُمَّ خَرَجْنَا مِنْ أَحَدِ أَبْوَابِ الْجَنَّةِ الثَّمَانِيَةِ فَلَمَّا كُنْتُ عِنْدَ الْبَابِ أُتِيتُ بِكِفَّةٍ فَوُضِعْتُ فِيهَا وَوُضِعَتْ أُمَّتِي فِي كِفَّةٍ فَرَجَحْتُ بِهَا ثُمَّ أُتِيَ ‏ ‏بِأَبِي بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَوُضِعَ فِي كِفَّةٍ وَجِيءَ بِجَمِيعِ أُمَّتِي فِي كِفَّةٍ فَوُضِعُوا فَرَجَحَ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَجِيءَ ‏ ‏بِعُمَرَ ‏ ‏فَوُضِعَ فِي كِفَّةٍ وَجِيءَ بِجَمِيعِ أُمَّتِي فَوُضِعُوا فَرَجَحَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏وَعُرِضَتْ أُمَّتِي رَجُلًا رَجُلًا فَجَعَلُوا يَمُرُّونَ ‏ ‏فَاسْتَبْطَأْتُ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ ‏ ‏ثُمَّ جَاءَ بَعْدَ ‏ ‏الْإِيَاسِ ‏ ‏فَقُلْتُ ‏ ‏عَبْدُ الرُّحْمَنِ ‏ ‏فَقَالَ بِأَبِي وَأُمِّي يَا رَسُولَ اللَّهِ وَالَّذِي بَعَثَكَ بِالْحَقِّ مَا خَلَصْتُ إِلَيْكَ حَتَّى ظَنَنْتُ أَنِّي لَا أَنْظُرُ إِلَيْكَ أَبَدًا إِلَّا بَعْدَ ‏ ‏الْمُشِيبَاتِ ‏ ‏قَالَ وَمَا ذَاكَ قَالَ مِنْ كَثْرَةِ مَالِي أُحَاسَبُ ‏ ‏وَأُمَحَّصُ ‏","","",""],[21204,21204,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ السِّيلَحِينِيُّ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سَعْدٍ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏أَبِي ظَبْيَةَ الشَّامِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمِقَةُ ‏ ‏فِي السَّمَاءِ فَإِذَا أَحَبَّ اللَّهُ عَبْدًا قَالَ ‏ ‏إِنِّي أَحْبَبْتُ فُلَانًا فَأَحِبُّوهُ قَالَ فَتَنْزِلُ لَهُ ‏ ‏الْمِقَةُ ‏ ‏فِي أَهْلِ الْأَرْضِ ‏","","",""],[21205,21205,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ السِّيلَحِينِيُّ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏إِنِّي لَتَحْتَ رَاحِلَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ الْفَتْحِ فَقَالَ قَوْلًا حَسَنًا جَمِيلًا وَكَانَ فِيمَا قَالَ ‏ ‏مَنْ أَسْلَمَ مِنْ أَهْلِ الْكِتَابَيْنِ فَلَهُ أَجْرُهُ مَرَّتَيْنِ وَلَهُ مَا لَنَا وَعَلَيْهِ مَا عَلَيْنَا وَمَنْ أَسْلَمَ مِنْ الْمُشْرِكِينَ فَلَهُ أَجْرُهُ وَلَهُ مَا لَنَا وَعَلَيْهِ مَا عَلَيْنَا ‏","","",""],[21206,21206,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَيُّوبَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ زَحْرٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ يَزِيدَ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏عُقْبَةُ بْنُ عَامِرٍ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ مَا النَّجَاةُ قَالَ ‏ ‏أَمْلِكْ عَلَيْكَ لِسَانَكَ وَلْيَسَعْكَ بَيْتُكَ وَابْكِ عَلَى خَطِيئَتِكَ ‏","","",""],[21207,21207,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏وَعَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَيُّوبَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ زَحْرٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ يَزِيدَ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مِنْ تَمَامِ ‏ ‏عِيَادَةِ ‏ ‏الْمَرِيضِ أَنْ يَضَعَ أَحَدُكُمْ يَدَهُ عَلَى جَبْهَتِهِ ‏ ‏أَوْ يَدِهِ ‏ ‏فَيَسْأَلُهُ كَيْفَ هُوَ وَتَمَامُ تَحِيَّاتِكُمْ بَيْنَكُمْ الْمُصَافَحَةُ ‏","","",""],[21208,21208,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ ذَرٍّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الرَّصَافَةِ ‏ ‏رَجُلٌ مِنْ أَهْلِ ‏ ‏الشَّامِ ‏ ‏مِنْ ‏ ‏بَاهِلَةَ ‏ ‏أَعْرَابِيٌّ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ امْرِئٍ مُسْلِمٍ تَحْضُرُهُ صَلَاةٌ مَكْتُوبَةٌ فَيَقُومُ فَيَتَوَضَّأُ فَيُحْسِنُ الْوُضُوءَ وَيُصَلِّي فَيُحْسِنُ الصَّلَاةَ إِلَّا غَفَرَ اللَّهُ لَهُ بِهَا مَا كَانَ بَيْنَهَا وَبَيْنَ الصَّلَاةِ الَّتِي كَانَتْ قَبْلَهَا مِنْ ذُنُوبِهِ ثُمَّ يَحْضُرُ صَلَاةً مَكْتُوبَةً فَيُصَلِّي فَيُحْسِنُ الصَّلَاةَ إِلَّا غُفِرَ لَهُ مَا بَيْنَهَا وَبَيْنَ الصَّلَاةِ الَّتِي كَانَتْ قَبْلَهَا مِنْ ذُنُوبِهِ ثُمَّ يَحْضُرُ صَلَاةً مَكْتُوبَةً فَيُصَلِّي فَيُحْسِنُ الصَّلَاةَ إِلَّا غُفِرَ لَهُ مَا بَيْنَهَا وَبَيْنَ الصَّلَاةِ الَّتِي كَانَتْ قَبْلَهَا مِنْ ذُنُوبِهِ ‏","","",""],[21209,21209,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏أَخْبَرَنِي ‏ ‏حُسَيْنٌ يَعْنِي ابْنَ وَاقِدٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو غَالِبٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا أُمَامَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْإِمَامُ ضَامِنٌ وَالْمُؤَذِّنُ مُؤْتَمَنٌ ‏","","",""],[21210,21210,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ الْهَاشِمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ يَعْنِي ابْنَ جَعْفَرٍ ‏ ‏أَخْبَرَنِي ‏ ‏الْعَلَاءُ ‏ ‏عَنْ ‏ ‏مَعْبَدِ بْنِ كَعْبٍ السُّلَمِيِّ ‏ ‏عَنْ ‏ ‏أَخِيهِ ‏ ‏عَبْدِ اللَّهِ بْنِ كَعْبٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ اقْتَطَعَ حَقَّ امْرِئٍ مُسْلِمٍ بِيَمِينِهِ فَقَدْ أَوْجَبَ اللَّهُ لَهُ بِهَا النَّارَ وَحَرَّمَ عَلَيْهِ الْجَنَّةَ فَقَالَ لَهُ رَجُلٌ وَإِنْ كَانَ شَيْئًا يَسِيرًا يَا رَسُولَ اللَّهِ قَالَ وَإِنْ ‏ ‏قَضِيبًا ‏ ‏مِنْ أَرَاكٍ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مَعْبَدِ بْنِ كَعْبٍ ‏ ‏فَذَكَرَ مِثْلَهُ إِلَّا أَنَّهُ قَالَ عَنْ ‏ ‏أَبِي أُمَامَةَ بْنِ سَهْلٍ ‏ ‏أَحَدِ ‏ ‏بَنِي حَارِثَةَ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏هَذَا ‏ ‏أَبُو أُمَامَةَ الْحَارِثِيُّ ‏ ‏وَلَيْسَ هُوَ ‏ ‏أَبَا أُمَامَةَ الْبَاهِلِيَّ ‏","","",""],[21211,21211,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏حَدَّثَنِي ‏ ‏مُعَاوِيَةُ بْنُ صَالِحٍ ‏ ‏حَدَّثَنِي ‏ ‏السَّفْرُ بْنُ نُسَيْرٍ الْأَزْدِيُّ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ شُرَيْحٍ الْحَضْرَمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا يَأْتِي أَحَدُكُمْ الصَّلَاةَ وَهُوَ ‏ ‏حَاقِنٌ ‏ ‏وَلَا يَؤُمَّنَّ أَحَدُكُمْ فَيَخُصَّ نَفْسَهُ بِالدُّعَاءِ دُونَهُمْ فَمَنْ فَعَلَ فَقَدْ خَانَهُمْ ‏","","",""],[21212,21212,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدٌ ‏ ‏حَدَّثَنِي ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو غَالِبٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو أُمَامَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏تَقْعُدُ الْمَلَائِكَةُ عَلَى أَبْوَابِ الْمَسَاجِدِ يَوْمَ الْجُمُعَةِ فَيَكْتُبُونَ الْأَوَّلَ وَالثَّانِيَ وَالثَّالِثَ حَتَّى إِذَا خَرَجَ الْإِمَامُ رُفِعَتْ الصُّحُفُ ‏","","",""],[21213,21213,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏أَخْبَرَنَا ‏ ‏حُسَيْنُ بْنُ وَاقِدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو غَالِبٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا أُمَامَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏التَّفْلُ فِي الْمَسْجِدِ سَيِّئَةٌ وَدَفْنُهُ حَسَنَةٌ ‏","","",""],[21214,21214,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏وَأَبُو الْمُغِيرَةِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَرِيزٌ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمُ بْنُ عَامِرٍ الْخَبَائِرِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا أُمَامَةَ ‏ ‏يَقُولُ ‏ ‏مَا كَانَ يَفْضُلُ مِنْ أَهْلِ بَيْتِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خُبْزُ الشَّعِيرِ ‏","","",""],[21215,21215,"","","‏ ‏حَدَّثَنَا ‏ ‏الْأَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ يَعْنِي ابْنَ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنِ ‏ ‏ابْنِ سَابِطٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُصَلُّوا عِنْدَ طُلُوعِ الشَّمْسِ فَإِنَّهَا تَطْلُعُ بَيْنَ قَرْنَيْ شَيْطَانٍ وَيَسْجُدُ لَهَا كُلُّ كَافِرٍ وَلَا عِنْدَ غُرُوبِهَا فَإِنَّهَا تَغْرُبُ بَيْنَ قَرْنَيْ شَيْطَانٍ وَيَسْجُدُ لَهَا كُلُّ كَافِرٍ وَلَا نِصْفَ النَّهَارِ فَإِنَّهُ عِنْدَ ‏ ‏سَجْرِ ‏ ‏جَهَنَّمَ ‏","","",""],[21216,21216,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ يَعْنِي ابْنَ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِي غَالِبٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّيهِمَا بَعْدَ ‏ ‏الْوِتْرِ ‏ ‏وَهُوَ جَالِسٌ يَقْرَأُ فِيهِمَا ‏ ‏إِذَا زُلْزِلَتْ الْأَرْضُ ‏ ‏وَقُلْ يَا أَيُّهَا الْكَافِرُونَ ‏","","",""],[21217,21217,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ أَبِي عِمْرَانَ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ الْبَاهِلِيِّ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏أَرْبَعَةٌ ‏ ‏تَجْرِي عَلَيْهِمْ أُجُورُهُمْ بَعْدَ الْمَوْتِ ‏ ‏مُرَابِطٌ ‏ ‏فِي سَبِيلِ اللَّهِ وَمَنْ عَمِلَ عَمَلًا أُجْرِيَ لَهُ مِثْلُ مَا عَمِلَ وَرَجُلٌ ‏ ‏تَصَدَّقَ ‏ ‏بِصَدَقَةٍ ‏ ‏فَأَجْرُهَا لَهُ مَا جَرَتْ وَرَجُلٌ تَرَكَ وَلَدًا صَالِحًا فَهُوَ يَدْعُو لَهُ ‏","","",""],[21218,21218,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَمْرُو بْنُ الْحَارِثِ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ ‏ ‏مَوْلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلَا يَلْبَسْ حَرِيرًا وَلَا ذَهَبًا ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏هَارُونَ بْنِ مَعْرُوفٍ ‏","","",""],[21219,21219,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنِي ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَلَا يَلْبَسْ حَرِيرًا وَلَا ذَهَبًا ‏","","",""],[21220,21220,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏حَرِيزٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مَيْسَرَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏أَبَا أُمَامَةَ ‏ ‏يَقُولُ ‏ ‏لَيَدْخُلَنَّ الْجَنَّةَ بِشَفَاعَةِ الرَّجُلِ الْوَاحِدِ لَيْسَ بِنَبِيٍّ مِثْلُ الْحَيَّيْنِ ‏ ‏أَوْ أَحَدِ الْحَيَّيْنِ ‏ ‏رَبِيعَةَ ‏ ‏وَمُضَرَ ‏ ‏قَالَ قَائِلٌ يَا رَسُولَ اللَّهِ أَوَمَا ‏ ‏رَبِيعَةُ ‏ ‏مِنْ ‏ ‏مُضَرَ ‏ ‏قَالَ إِنَّمَا أَقُولُ مَا أُقَوَّلُ ‏","","",""],[21221,21221,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ أَبِي جَعْفَرٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ أَبِي عِمْرَانَ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ شَفَعَ لِأَحَدٍ شَفَاعَةً فَأَهْدَى لَهُ هَدِيَّةً فَقَبِلَهَا فَقَدْ أَتَى بَابًا عَظِيمًا مِنْ الرِّبَا ‏","","",""],[21222,21222,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ يَعْنِي ابْنَ صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي الْمُهَلَّبِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ زَحْرٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ يَزِيدَ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ بَدَأَ بِالسَّلَامِ فَهُوَ أَوْلَى بِاللَّهِ وَبِرَسُولِهِ ‏","","",""],[21223,21223,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ بْنُ الْحَجَّاجِ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ الْحِمْصِيِّ ‏ ‏قَالَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الْوُضُوءَ يُكَفِّرُ مَا قَبْلَهُ ثُمَّ تَصِيرُ الصَّلَاةُ ‏ ‏نَافِلَةً ‏ ‏قَالَ فَقِيلَ لَهُ أَنْتَ سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ نَعَمْ غَيْرَ مَرَّةٍ وَلَا مَرَّتَيْنِ وَلَا ثَلَاثٍ وَلَا أَرْبَعٍ وَلَا خَمْسٍ ‏","","",""],[21224,21224,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي التَّيَّاحِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الْجَعْدِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏قَاصٍّ ‏ ‏يَقُصُّ فَأَمْسَكَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُصَّ فَلَأَنْ أَقْعُدَ غُدْوَةً إِلَى أَنْ تُشْرِقَ الشَّمْسُ أَحَبُّ إِلَيَّ مِنْ أَنْ أُعْتِقَ أَرْبَعَ رِقَابٍ وَبَعْدَ الْعَصْرِ حَتَّى تَغْرُبَ الشَّمْسُ أَحَبُّ إِلَيَّ مِنْ أَنْ أُعْتِقَ أَرْبَعَ رِقَابٍ ‏","","",""],[21225,21225,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ صَالِحٍ ‏ ‏عَنْ ‏ ‏السَّفْرِ بْنِ نُسَيْرٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ شُرَيْحٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا أُمَامَةَ ‏ ‏يُحَدِّثُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَأْتِ أَحَدُكُمْ الصَّلَاةَ وَهُوَ ‏ ‏حَاقِنٌ ‏ ‏وَلَا يَخُصَّ نَفْسَهُ بِشَيْءٍ دُونَ أَصْحَابِهِ وَلَا يُدْخِلْ عَيْنَيْهِ بَيْتًا حَتَّى يَسْتَأْذِنَ ‏ ‏فَقَالَ ‏ ‏شَيْخٌ ‏ ‏لَمَّا ‏ ‏حَدَّثَهُ ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا سَمِعْتُ ‏ ‏أَبَا أُمَامَةَ ‏ ‏يُحَدِّثُ بِهَذَا الْحَدِيثِ ‏","","",""],[21226,21226,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ يَعْنِي ابْنَ صَالِحٍ ‏ ‏عَنْ ‏ ‏عَامِرِ بْنِ جَشِيبٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏قَالَ ‏ ‏حَضَرْنَا صَنِيعًا ‏ ‏لِعَبْدِ الْأَعْلَى بْنِ هِلَالٍ ‏ ‏فَلَمَّا فَرَغْنَا مِنْ الطَّعَامِ قَامَ ‏ ‏أَبُو أُمَامَةَ ‏ ‏فَقَالَ لَقَدْ قُمْتُ مَقَامِي هَذَا وَمَا أَنَا بِخَطِيبٍ وَمَا أُرِيدُ الْخُطْبَةَ وَلَكِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ عِنْدَ انْقِضَاءِ الطَّعَامِ ‏ ‏الْحَمْدُ لِلَّهِ كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ غَيْرَ مَكْفِيٍّ وَلَا مُوَدَّعٍ وَلَا مُسْتَغْنًى عَنْهُ قَالَ فَلَمْ يَزَلْ يُرَدِّدُهُنَّ عَلَيْنَا حَتَّى حَفِظْنَاهُنَّ ‏","","",""],[21227,21227,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي عُتْبَةَ الْكِنْدِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ أُمَّتِي أَحَدٌ إِلَّا وَأَنَا أَعْرِفُهُ يَوْمَ الْقِيَامَةِ قَالُوا يَا رَسُولَ اللَّهِ ‏ ‏مَنْ رَأَيْتَ وَمَنْ لَمْ تَرَ قَالَ مَنْ رَأَيْتُ وَمَنْ لَمْ أَرَ غُرًّا مُحَجَّلِينَ مِنْ أَثَرِ الطُّهُورِ ‏","","",""],[21228,21228,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ صَالِحٍ ‏ ‏عَنْ ‏ ‏سُلَيْمِ بْنِ عَامِرٍ الْكَلَاعِيِّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا أُمَامَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَوْمَئِذٍ عَلَى ‏ ‏الْجَدْعَاءِ ‏ ‏وَاضِعٌ رِجْلَيْهِ فِي ‏ ‏الْغَرْزِ ‏ ‏يَتَطَاوَلُ يُسْمِعُ النَّاسَ فَقَالَ بِأَعْلَى صَوْتِهِ أَلَا تَسْمَعُونَ فَقَالَ رَجُلٌ مِنْ طَوَائِفِ النَّاسِ يَا رَسُولَ اللَّهِ مَاذَا تَعْهَدُ إِلَيْنَا قَالَ ‏ ‏اعْبَدُوا رَبَّكُمْ وَصَلُّوا خَمْسَكُمْ وَصُومُوا شَهْرَكُمْ وَأَطِيعُوا ذَا أَمْرِكُمْ تَدْخُلُوا جَنَّةَ رَبِّكُمْ فَقُلْتُ يَا ‏ ‏أَبَا أُمَامَةَ ‏ ‏مِثْلُ مَنْ أَنْتَ يَوْمَئِذٍ قَالَ أَنَا يَوْمَئِذٍ ابْنُ ثَلَاثِينَ سَنَةً أُزَاحِمُ الْبَعِيرَ أُزَحْزِحُهُ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[21229,21229,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏أَبِي غَالِبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا أُمَامَةَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي قَوْلِهِ عَزَّ وَجَلَّ ‏ { ‏فَأَمَّا الَّذِينَ فِي قُلُوبِهِمْ زَيْغٌ فَيَتَّبِعُونَ مَا تَشَابَهَ مِنْهُ ‏} ‏قَالَ هُمْ ‏ ‏الْخَوَارِجُ ‏ ‏وَفِي قَوْلِهِ ‏ { ‏يَوْمَ تَبْيَضُّ وُجُوهٌ وَتَسْوَدُّ وُجُوهٌ ‏} ‏قَالَ هُمْ ‏ ‏الْخَوَارِجُ ‏","","",""],[21230,21230,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏فَرَجُ بْنُ فَضَالَةَ ‏ ‏حَدَّثَنَا ‏ ‏لُقْمَانُ بْنُ عَامِرٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏حَجَجْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَجَّةَ الْوَدَاعِ فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ ثُمَّ قَالَ أَلَا لَعَلَّكُمْ لَا تَرَوْنِي بَعْدَ عَامِكُمْ هَذَا أَلَا لَعَلَّكُمْ لَا تَرَوْنِي بَعْدَ عَامِكُمْ هَذَا أَلَا لَعَلَّكُمْ لَا تَرَوْنِي بَعْدَ عَامِكُمْ هَذَا فَقَامَ رَجُلٌ طَوِيلٌ كَأَنَّهُ مِنْ رِجَالِ ‏ ‏شَنُوءَةَ ‏ ‏فَقَالَ يَا نَبِيَّ اللَّهِ فَمَا الَّذِي نَفْعَلُ فَقَالَ ‏ ‏اعْبُدُوا رَبَّكُمْ وَصَلُّوا خَمْسَكُمْ وَصُومُوا شَهْرَكُمْ وَحُجُّوا بَيْتَكُمْ وَأَدُّوا زَكَاتَكُمْ طَيِّبَةً بِهَا أَنْفُسُكُمْ تَدْخُلُوا جَنَّةَ رَبِّكُمْ عَزَّ وَجَلَّ ‏","","",""],[21231,21231,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏الْفَرَجُ ‏ ‏حَدَّثَنَا ‏ ‏لُقْمَانُ بْنُ عَامِرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا أُمَامَةَ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا نَبِيَّ اللَّهِ مَا كَانَ أَوَّلُ بَدْءِ أَمْرِكَ قَالَ ‏ ‏دَعْوَةُ أَبِي ‏ ‏إِبْرَاهِيمَ ‏ ‏وَبُشْرَى ‏ ‏عِيسَى ‏ ‏وَرَأَتْ أُمِّي أَنَّهُ يَخْرُجُ مِنْهَا نُورٌ أَضَاءَتْ مِنْهَا قُصُورُ ‏ ‏الشَّامِ ‏","","",""],[21232,21232,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏فَرَجٌ ‏ ‏حَدَّثَنَا ‏ ‏لُقْمَانُ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ قَتْلِ عَوَامِرِ الْبُيُوتِ إِلَّا مِنْ ذِي الطُّفْيَتَيْنِ وَالْأَبْتَرِ فَإِنَّهُمَا ‏ ‏يُكْمِهَانِ الْأَبْصَارَ وَتَخْدِجُ مِنْهُنَّ النِّسَاءُ ‏","","",""],[21233,21233,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏فَرَجٌ ‏ ‏حَدَّثَنَا ‏ ‏لُقْمَانُ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ وَمَلَائِكَتَهُ يُصَلُّونَ عَلَى الصَّفِّ الْأَوَّلِ قَالُوا يَا رَسُولَ اللَّهِ وَعَلَى الثَّانِي قَالَ إِنَّ اللَّهَ وَمَلَائِكَتَهُ يُصَلُّونَ عَلَى الصَّفِّ الْأَوَّلِ قَالُوا يَا رَسُولَ اللَّهِ وَعَلَى الثَّانِي قَالَ وَعَلَى الثَّانِي قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَوُّوا صُفُوفَكُمْ وَحَاذُوا بَيْنَ مَنَاكِبِكُمْ وَلِينُوا فِي أَيْدِي إِخْوَانِكُمْ وَسُدُّوا الْخَلَلَ فَإِنَّ الشَّيْطَانَ يَدْخُلُ بَيْنَكُمْ بِمَنْزِلَةِ الْحَذَفِ ‏ ‏يَعْنِي أَوْلَادَ الضَّأْنِ الصِّغَارَ ‏","","",""],[21234,21234,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏الْفَرَجُ ‏ ‏حَدَّثَنَا ‏ ‏لُقْمَانُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا أُمَامَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَجِيفُوا أَبْوَابَكُمْ وَأَكْفِئُوا آنِيَتَكُمْ ‏ ‏وَأَوْكِئُوا أَسْقِيَتَكُمْ وَأَطْفِئُوا سُرُجَكُمْ فَإِنَّهُ لَنْ يُؤْذَنَ لَهُمْ بِالتَّسَوُّرِ عَلَيْكُمْ ‏","","",""],[21235,21235,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُوحٍ قُرَادٌ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏سَمِعْتُ أَبِي غَيْرَ مَرَّةٍ يَقُولُ وَحِدْثنَا ‏ ‏أَبُو نُوحٍ قُرَادٌ ‏ ‏حَدَّثَنَا ‏ ‏عِكْرِمَةُ بْنُ عَمَّارٍ ‏ ‏عَنْ ‏ ‏شَدَّادِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا أُمَامَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ يَا ابْنَ ‏ ‏آدَمَ ‏ ‏إِنَّكَ إِنْ تَبْذُلْ الْخَيْرَ خَيْرٌ لَكَ وَإِنْ تُمْسِكْهُ شَرٌّ لَكَ وَلَا تُلَامُ عَلَى الْكَفَافِ وَابْدَأْ بِمَنْ تَعُولُ وَالْيَدُ الْعُلْيَا خَيْرٌ مِنْ الْيَدِ السُّفْلَى ‏","","",""],[21236,21236,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُوحٍ ‏ ‏وَعَبْدُ الصَّمَدِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عِكْرِمَةُ ‏ ‏وَقَالَ ‏ ‏أَبُو نُوحٍ ‏ ‏أَخْبَرَنَا ‏ ‏عِكْرِمَةُ بْنُ عَمَّارٍ ‏ ‏عَنْ ‏ ‏شَدَّادِ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا أُمَامَةَ ‏ ‏يَقُولُ ‏ ‏أَتَى رَجُلٌ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ فِي الْمَسْجِدِ فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي أَصَبْتُ ‏ ‏حَدًّا ‏ ‏فَأَقِمْهُ عَلَيَّ قَالَ فَسَكَتَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ عَادَ فَقَالَ لَهُ مَرَّةً أُخْرَى ثُمَّ أُقِيمَتْ الصَّلَاةُ فَصَلَّى ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ انْصَرَفَ قَالَ ‏ ‏أَبُو أُمَامَةَ ‏ ‏فَاتَّبَعَهُ الرَّجُلُ قَالَ وَتَبِعْتُهُ ‏ ‏قَالَ ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏فِي حَدِيثِهِ ‏ ‏فَانْصَرَفْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالرَّجُلُ يَتْبَعُهُ لِأَعْلَمَ مَا يَقُولُ لَهُ قَالَ فَقَالَ لَهُ الرَّجُلُ يَا رَسُولَ اللَّهِ إِنِّي أَصَبْتُ حَدًّا فَأَقِمْهُ عَلَيَّ قَالَ فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَيْسَ قَدْ تَوَضَّأْتَ قَبْلَ أَنْ تَخْرُجَ مِنْ مَنْزِلِكَ فَأَحْسَنْتَ الْوُضُوءَ ثُمَّ صَلَّيْتَ مَعَنَا قَالَ بَلَى قَالَ فَإِنَّ اللَّهَ قَدْ غَفَرَ لَكَ حَدَّكَ ‏ ‏أَوْ ذَنْبَكَ شَكَّ فِيهِ ‏ ‏عِكْرِمَةُ ‏ ‏قَالَ ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏فِي حَدِيثِهِ فَانْصَرَفْتُ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاتَّبَعَهُ الرَّجُلُ ‏","","",""],[21237,21237,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ بْنُ بَهْرَامَ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو أُمَامَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَيُّمَا رَجُلٍ قَامَ إِلَى وَضُوئِهِ يُرِيدُ الصَّلَاةَ ثُمَّ غَسَلَ كَفَّيْهِ نَزَلَتْ خَطِيئَتُهُ مِنْ كَفَّيْهِ مَعَ أَوَّلِ قَطْرَةٍ فَإِذَا مَضْمَضَ وَاسْتَنْشَقَ وَاسْتَنْثَرَ نَزَلَتْ خَطِيئَتُهُ مِنْ لِسَانِهِ وَشَفَتَيْهِ مَعَ أَوَّلِ قَطْرَةٍ فَإِذَا غَسَلَ وَجْهَهُ نَزَلَتْ خَطِيئَتُهُ مِنْ سَمْعِهِ وَبَصَرِهِ مَعَ أَوَّلِ قَطْرَةٍ فَإِذَا غَسَلَ يَدَيْهِ إِلَى الْمِرْفَقَيْنِ وَرِجْلَيْهِ إِلَى الْكَعْبَيْنِ سَلِمَ مِنْ كُلِّ ذَنْبٍ هُوَ لَهُ وَمِنْ كُلِّ خَطِيئَةٍ كَهَيْئَتِهِ يَوْمَ وَلَدَتْهُ أُمُّهُ قَالَ فَإِذَا قَامَ إِلَى الصَّلَاةِ رَفَعَ اللَّهُ بِهَا دَرَجَتَهُ وَإِنْ قَعَدَ قَعَدَ سَالِمًا ‏","","",""],[21238,21238,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏مُبَارَكٌ يَعْنِي ابْنَ فَضَالَةَ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو غَالِبٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَقْعُدُ الْمَلَائِكَةُ يَوْمَ الْجُمُعَةِ عَلَى أَبْوَابِ الْمَسْجِدِ مَعَهُمْ الصُّحُفُ يَكْتُبُونَ النَّاسَ فَإِذَا خَرَجَ الْإِمَامُ طُوِيَتْ الصُّحُفُ قُلْتُ يَا ‏ ‏أَبَا أُمَامَةَ ‏ ‏لَيْسَ لِمَنْ جَاءَ بَعْدَ خُرُوجِ الْإِمَامِ جُمُعَةٌ قَالَ بَلَى وَلَكِنْ لَيْسَ مِمَّنْ يُكْتَبُ فِي الصُّحُفِ ‏","","",""],[21239,21239,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ وَهْبٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَيُّوبَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ زَحْرٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا جَاءَنِي ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏قَطُّ إِلَّا أَمَرَنِي بِالسِّوَاكِ لَقَدْ خَشِيتُ أَنْ أُحْفِيَ مُقَدَّمَ ‏ ‏فِيَّ ‏","","",""],[21240,21240,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سَعْدٍ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏أَبِي ظَبْيَةَ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الْمِقَةَ مِنْ اللَّهِ ‏ ‏قَالَ ‏ ‏شَرِيكٌ ‏ ‏هِيَ الْمَحَبَّةُ ‏ ‏وَأُلْقِيَتْ مِنْ السَّمَاءِ فَإِذَا أَحَبَّ اللَّهُ عَبْدًا قَالَ ‏ ‏لِجِبْرِيلَ ‏ ‏إِنِّي أُحِبُّ فُلَانًا فَيُنَادِي ‏ ‏جِبْرِيلُ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ يَمِقُ ‏ ‏يَعْنِي يُحِبُّ ‏ ‏فُلَانًا فَأَحِبُّوهُ ‏ ‏أَرَى ‏ ‏شَرِيكًا ‏ ‏قَدْ قَالَ فَيُنْزِلُ لَهُ الْمَحَبَّةَ فِي الْأَرْضِ ‏ ‏وَإِذَا أَبْغَضَ عَبْدًا قَالَ ‏ ‏لِجِبْرِيلَ ‏ ‏إِنِّي أُبْغِضُ فُلَانًا فَأَبْغِضْهُ قَالَ فَيُنَادِي ‏ ‏جِبْرِيلُ ‏ ‏إِنَّ رَبَّكُمْ يُبْغِضُ فُلَانًا فَأَبْغِضُوهُ قَالَ ‏ ‏أَرَى ‏ ‏شَرِيكًا ‏ ‏قَدْ قَالَ ‏ ‏فَيَجْرِي لَهُ الْبُغْضُ فِي الْأَرْضِ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ حَكِيمٍ الْأَوْدِيُّ ‏ ‏أَخْبَرَنَا ‏ ‏شَرِيكٌ ‏ ‏و حَدَّثَنِي ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏أَبِي ظَبْيَةَ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَهُ ‏","","",""],[21241,21241,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ الزُّبَيْرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ يَعْنِي ابْنَ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُسْلِمٍ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏أَبِي أُمَامَةَ ‏ ‏وَهُوَ ‏ ‏يَتَفَلَّى فِي الْمَسْجِدِ وَيَدْفِنُ الْقَمْلَ فِي الْحَصَى فَقُلْتُ لَهُ يَا ‏ ‏أَبَا أُمَامَةَ ‏ ‏إِنَّ رَجُلًا حَدَّثَنِي عَنْكَ أَنَّكَ قُلْتَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ تَوَضَّأَ فَأَسْبَغَ الْوُضُوءَ فَغَسَلَ يَدَيْهِ وَوَجْهَهُ وَمَسَحَ عَلَى رَأْسِهِ وَأُذُنَيْهِ ثُمَّ قَامَ إِلَى الصَّلَاةِ الْمَفْرُوضَةِ غَفَرَ اللَّهُ لَهُ فِي ذَلِكَ الْيَوْمِ مَا مَشَتْ إِلَيْهِ رِجْلُهُ وَقَبَضَتْ عَلَيْهِ يَدَاهُ وَسَمِعَتْ إِلَيْهِ أُذُنَاهُ وَنَظَرَتْ إِلَيْهِ عَيْنَاهُ وَحَدَّثَ بِهِ نَفْسَهُ مِنْ سُوءٍ قَالَ وَاللَّهِ لَقَدْ سَمِعْتُهُ مِنْ نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا لَا ‏ ‏أُحْصِيهِ ‏","","",""],[21242,21242,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ الْوَاسِطِيُّ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ أَبِي الْعَاتِكَةِ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةٌ فِي ‏ ‏دُبُرِ ‏ ‏صَلَاةٍ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَقَالَ ‏ ‏غَيْرُهُ فِي إِثْرِ صَلَاةٍ ‏ ‏لَا لَغْوَ بَيْنَهُمَا كِتَابٌ فِي عِلِّيِّينَ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏قُلْتُ لِأَبِي مِنْ أَيْنَ سَمِعَ ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ أَبِي الْعَاتِكَةِ ‏ ‏قَالَ كَانَ أَصْلُهُ شَامِيًّا سَمِعَ مِنْهُ ‏ ‏بِالشَّامِ ‏","","",""],[21243,21243,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ مُطَرِّفٍ أَبُو غَسَّانَ اللَّيْثِيُّ ‏ ‏عَنْ ‏ ‏أَبِي الْحَصِينِ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ الْأَشْعَرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْحُمَّى كِيرٌ مِنْ جَهَنَّمَ فَمَا أَصَابَ الْمُؤْمِنَ مِنْهَا كَانَ حَظَّهُ مِنْ جَهَنَّمَ ‏","","",""],[21244,21244,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏وَأَبُو سَعِيدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمُ بْنُ أَبِي النَّجُودِ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏لَوْ لَمْ أَسْمَعْهُ مِنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا سَبْعًا ‏ ‏قَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏إِلَّا سَبْعَ مِرَارٍ ‏ ‏مَا حَدَّثَ بِهِ قَالَ ‏ ‏إِذَا تَوَضَّأَ الرَّجُلُ كَمَا أُمِرَ ذَهَبَ الْإِثْمُ مِنْ سَمْعِهِ وَبَصَرِهِ وَيَدَيْهِ وَرِجْلَيْهِ ‏","","",""],[21245,21245,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي يَعْقُوبَ ‏ ‏سَمِعَ ‏ ‏أَبَا نَصْرٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ أَخْبِرْنِي بِعَمَلٍ يُدْخِلُنِي الْجَنَّةَ قَالَ ‏ ‏عَلَيْكَ بِالصَّوْمِ فَإِنَّهُ لَا عِدْلَ لَهُ ‏ ‏أَوْ قَالَ لَا مِثْلَ لَهُ ‏","","",""],[21246,21246,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَيْمَنَ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏طُوبَى ‏ ‏لِمَنْ رَآنِي ‏ ‏وَطُوبَى ‏ ‏سَبْعَ مِرَارٍ لِمَنْ آمَنْ بِي وَلَمْ يَرَنِي ‏","","",""],[21247,21247,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ مُبَارَكٍ ‏ ‏وَعَتَّابٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ هُوَ ابْنُ الْمُبَارَكِ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ زَحْرٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ مُسْلِمٍ يَنْظُرُ إِلَى مَحَاسِنِ امْرَأَةٍ أَوَّلَ مَرَّةٍ ثُمَّ يَغُضُّ بَصَرَهُ إِلَّا أَحْدَثَ اللَّهُ لَهُ عِبَادَةً يَجِدُ حَلَاوَتَهَا ‏","","",""],[21248,21248,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ مُضَرَ ‏ ‏حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ زَحْرٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ يَزِيدَ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏يَرْفَعُ الْحَدِيثَ قَالَ ‏ ‏مَنْ بَدَأَ بِالسَّلَامِ فَهُوَ أَوْلَى بِاللَّهِ عَزَّ وَجَلَّ وَرَسُولِهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[21249,21249,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏بَكْرُ بْنُ مُضَرَ ‏ ‏حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ زَحْرٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَبِيعُوا الْمُغَنِّيَاتِ وَلَا تَشْتَرُوهُنَّ وَلَا تُعَلِّمُوهُنَّ وَلَا خَيْرَ فِي تِجَارَةٍ فِيهِنَّ وَثَمَنُهُنَّ حَرَامٌ ‏","","",""],[21250,21250,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏لَوْ لَمْ أَسْمَعْهُ مِنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَّا سَبْعَ مِرَارٍ مَا حَدَّثْتُ بِهِ قَالَ ‏ ‏إِذَا تَوَضَّأَ الرَّجُلُ كَمَا أُمِرَ ذَهَبَ الْإِثْمُ مِنْ سَمْعِهِ وَبَصَرِهِ وَيَدَيْهِ وَرِجْلَيْهِ ‏","","",""],[21251,21251,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏سِنَانِ بْنِ رَبِيعَةَ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ فَغَسَلَ وَجْهَهُ ثَلَاثًا وَيَدَيْهِ ثَلَاثًا ثَلَاثًا وَمَسَحَ بِرَأْسِهِ وَقَالَ الْأُذُنَانِ مِنْ الرَّأْسِ ‏ ‏قَالَ ‏ ‏حَمَّادٌ ‏ ‏فَلَا أَدْرِي مِنْ قَوْلِ ‏ ‏أَبِي أُمَامَةَ ‏ ‏أَوْ مِنْ قَوْلِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْسَحُ عَلَى الْمُوقَيْنِ ‏","","",""],[21252,21252,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْعَلَاءِ بْنِ زَبْرٍ ‏ ‏حَدَّثَنِي ‏ ‏الْقَاسِمُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا أُمَامَةَ ‏ ‏يَقُولُ ‏ ‏خَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى مَشْيَخَةٍ مِنْ ‏ ‏الْأَنْصَارٍ ‏ ‏بِيضٌ لِحَاهُمْ فَقَالَ يَا مَعْشَرَ ‏ ‏الْأَنْصَارِ ‏ ‏حَمِّرُوا وَصَفِّرُوا وَخَالِفُوا ‏ ‏أَهْلَ الْكِتَابِ ‏ ‏قَالَ فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏أَهْلَ الْكِتَابِ ‏ ‏يَتَسَرْوَلَونَ وَلَا ‏ ‏يَأْتَزِرُونَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَسَرْوَلُوا ‏ ‏وَائْتَزِرُوا وَخَالِفُوا ‏ ‏أَهْلَ الْكِتَابِ ‏ ‏قَالَ فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏أَهْلَ الْكِتَابِ ‏ ‏يَتَخَفَّفُونَ وَلَا يَنْتَعِلُونَ قَالَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَتَخَفَّفُوا وَانْتَعِلُوا وَخَالِفُوا ‏ ‏أَهْلَ الْكِتَابِ ‏ ‏قَالَ فَقُلْنَا يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏أَهْلَ الْكِتَابِ ‏ ‏يَقُصُّونَ ‏ ‏عَثَانِينَهُمْ وَيُوَفِّرُونَ سِبَالَهُمْ قَالَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُصُّوا سِبَالَكُمْ وَوَفِّرُوا ‏ ‏عَثَانِينَكُمْ وَخَالِفُوا ‏ ‏أَهْلَ الْكِتَابِ ‏","","",""],[21253,21253,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ زَحْرٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ مَسَحَ رَأْسَ يَتِيمٍ أَوْ يَتِيمَةٍ لَمْ يَمْسَحْهُ إِلَّا لِلَّهِ كَانَ لَهُ بِكُلِّ شَعْرَةٍ مَرَّتْ عَلَيْهَا يَدُهُ حَسَنَاتٌ وَمَنْ أَحْسَنَ إِلَى يَتِيمَةٍ أَوْ يَتِيمٍ عِنْدَهُ كُنْتُ أَنَا وَهُوَ فِي الْجَنَّةِ كَهَاتَيْنِ وَقَرَنَ بَيْنَ أُصْبُعَيْهِ ‏","","",""],[21254,21254,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏صَفْوَانُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ بُسْرٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي قَوْلِهِ ‏ { ‏وَيُسْقَى مِنْ مَاءٍ صَدِيدٍ ‏ ‏يَتَجَرَّعُهُ ‏ } ‏قَالَ يُقَرَّبُ إِلَيْهِ فَيَتَكَرَّهُهُ فَإِذَا دَنَا مِنْهُ شُوِيَ وَجْهُهُ وَوَقَعَتْ فَرْوَةُ رَأْسِهِ وَإِذَا شَرِبَهُ قَطَّعَ أَمْعَاءَهُ حَتَّى خَرَجَ مِنْ ‏ ‏دُبُرِهِ ‏ ‏يَقُولُ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏وَسُقُوا مَاءً حَمِيمًا فَقَطَّعَ أَمْعَاءَهُمْ ‏} ‏وَيَقُولُ اللَّهُ ‏ { ‏وَإِنْ يَسْتَغِيثُوا يُغَاثُوا بِمَاءٍ كَالْمُهْلِ ‏ ‏يَشْوِي الْوُجُوهَ بِئْسَ الشَّرَابُ ‏}","","",""],[21255,21255,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو عَمَّارٍ شَدَّادٌ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو أُمَامَةَ ‏ ‏أَنَّ رَجُلًا أَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي أَصَبْتُ ‏ ‏حَدًّا ‏ ‏فَأَقِمْهُ عَلَيَّ فَأَعْرَضَ عَنْهُ ثُمَّ قَالَ إِنِّي أَصَبْتُ ‏ ‏حَدًّا ‏ ‏فَأَقِمْهُ عَلَيَّ فَأَعْرَضَ عَنْهُ ثُمَّ قَالَ يَا رَسُولَ اللَّهِ إِنِّي أَصَبْتُ حَدًّا فَأَقِمْهُ عَلَيَّ فَأَعْرَضَ عَنْهُ وَأُقِيمَتْ الصَّلَاةُ فَلَمَّا سَلَّمَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَامَ فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي أَصَبْتُ ‏ ‏حَدًّا ‏ ‏فَأَقِمْهُ عَلَيَّ فَقَالَ ‏ ‏هَلْ تَوَضَّأْتَ حِينَ أَقْبَلْتَ قَالَ نَعَمْ فَقَالَ هَلْ صَلَّيْتَ مَعَنَا حِينَ صَلَّيْنَا قَالَ نَعَمْ قَالَ اذْهَبْ فَإِنَّ اللَّهَ قَدْ عَفَا عَنْكَ ‏","","",""],[21256,21256,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَانُ بْنُ رِفَاعَةَ ‏ ‏حَدَّثَنِي ‏ ‏عَلِيُّ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَمَا هُوَ يَمْشِي فِي شِدَّةِ حَرٍّ انْقَطَعَ شِسْعُ نَعْلِهِ فَجَاءَهُ رَجُلٌ بِشِسْعٍ فَوَضَعَهُ فِي نَعْلِهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْ تَعْلَمُ مَا حَمَلْتَ عَلَيْهِ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَعْلُ مَا حَمَلْتَ عَلَيْهِ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[21257,21257,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَانُ بْنُ رِفَاعَةَ ‏ ‏حَدَّثَنِي ‏ ‏عَلِيُّ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْمَسْجِدِ جَالِسًا وَكَانُوا يَظُنُّونَ أَنَّهُ يَنْزِلُ عَلَيْهِ فَأَقْصَرُوا عَنْهُ حَتَّى جَاءَ ‏ ‏أَبُو ذَرٍّ ‏ ‏فَاقْتَحَمَ فَأَتَى فَجَلَسَ إِلَيْهِ فَأَقْبَلَ عَلَيْهِمْ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا ‏ ‏أَبَا ذَرٍّ ‏ ‏هَلْ صَلَّيْتَ الْيَوْمَ قَالَ لَا قَالَ قُمْ فَصَلِّ فَلَمَّا صَلَّى أَرْبَعَ رَكَعَاتٍ الضُّحَى أَقْبَلَ عَلَيْهِ فَقَالَ يَا ‏ ‏أَبَا ذَرٍّ ‏ ‏تَعَوَّذْ مِنْ شَرِّ شَيَاطِينِ الْجِنِّ وَالْإِنْسِ قَالَ يَا نَبِيَّ اللَّهِ وَهَلْ لَلْإِنْسِ شَيَاطِينٌ قَالَ نَعَمْ شَيَاطِينُ الْإِنْسِ وَالْجِنِّ يُوحِي بَعْضُهُمْ إِلَى بَعْضٍ زُخْرُفَ الْقَوْلِ غُرُورًا ثُمَّ قَالَ يَا ‏ ‏أَبَا ذَرٍّ ‏ ‏أَلَا أُعَلِّمُكَ مِنْ كَنْزِ الْجَنَّةِ قَالَ بَلَى جَعَلَنِي اللَّهُ فِدَاءَكَ قَالَ قُلْ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ قَالَ فَقُلْتُ لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ قَالَ ثُمَّ سَكَتَ عَنِّي فَاسْتَبْطَأْتُ كَلَامَهُ قَالَ قُلْتُ يَا نَبِيَّ اللَّهِ إِنَّا كُنَّا أَهْلَ جَاهِلِيَّةٍ وَعَبَدَةَ أَوْثَانٍ فَبَعَثَكَ اللَّهُ رَحْمَةً لِلْعَالَمِينَ أَرَأَيْتَ الصَّلَاةَ مَاذَا هِيَ قَالَ خَيْرٌ مَوْضُوعٌ مَنْ شَاءَ اسْتَقَلَّ وَمَنْ شَاءَ اسْتَكْثَرَ قَالَ قُلْتُ يَا نَبِيَّ اللَّهِ أَرَأَيْتَ الصِّيَامَ مَاذَا هُوَ قَالَ فَرْضٌ مُجْزِئٌ قَالَ قُلْتُ يَا نَبِيَّ اللَّهِ أَرَأَيْتَ ‏ ‏الصَّدَقَةَ ‏ ‏مَاذَا هِيَ قَالَ أَضْعَافٌ مُضَاعَفَةٌ وَعِنْدَ اللَّهِ الْمَزِيدُ قَالَ قُلْتُ يَا نَبِيَّ اللَّهِ فَأَيُّ ‏ ‏الصَّدَقَةِ ‏ ‏أَفْضَلُ قَالَ سِرٌّ إِلَى فَقِيرٍ ‏ ‏وَجُهْدٌ ‏ ‏مِنْ مُقِلٍّ قَالَ قُلْتُ يَا نَبِيَّ اللَّهِ أَيُّمَا نَزَلَ عَلَيْكَ أَعْظَمُ قَالَ ‏ { ‏اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ‏} ‏آيَةُ الْكُرْسِيِّ ‏ ‏قَالَ قُلْتُ يَا نَبِيَّ اللَّهِ أَيُّ الشُّهَدَاءِ أَفْضَلُ قَالَ مَنْ سُفِكَ دَمُهُ وَعُقِرَ جَوَادُهُ قَالَ قُلْتُ يَا نَبِيَّ اللَّهِ فَأَيُّ الرِّقَابِ أَفْضَلُ قَالَ أَغْلَاهَا ثَمَنًا وَأَنْفَسُهَا عِنْدَ أَهْلِهَا قَالَ قُلْتُ يَا نَبِيَّ اللَّهِ فَأَيُّ الْأَنْبِيَاءِ كَانَ أَوَّلَ قَالَ ‏ ‏آدَمُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏قَالَ قُلْتُ يَا نَبِيَّ اللَّهِ أَوَنَبِيٌّ كَانَ ‏ ‏آدَمُ ‏ ‏قَالَ نَعَمْ نَبِيٌّ مُكَلَّمٌ خَلَقَهُ ‏ ‏اللَّهُ بِيَدِهِ ثُمَّ نَفَخَ فِيهِ رُوحَهُ ثُمَّ قَالَ لَهُ يَا ‏ ‏آدَمُ ‏ ‏قُبْلًا قَالَ قُلْتُ يَا رَسُولَ اللَّهِ كَمْ وَفَّى عِدَّةُ الْأَنْبِيَاءِ قَالَ مِائَةُ أَلْفٍ وَأَرْبَعَةٌ وَعِشْرُونَ أَلْفًا الرُّسُلُ مِنْ ذَلِكَ ثَلَاثُ مِائَةٍ وَخَمْسَةَ عَشَرَ جَمًّا غَفِيرًا ‏","","",""],[21258,21258,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَانُ بْنُ رِفَاعَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَلِيُّ بْنُ يَزِيدَ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏مَرَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِرَجُلٍ وَهُوَ يَقْرَأُ ‏ ‏قُلْ هُوَ اللَّهُ أَحَدٌ ‏ ‏فَقَالَ ‏ ‏أَوْجَبَ هَذَا ‏ ‏أَيْ وَجَبَتْ لِهَذَا ‏ ‏الْجَنَّةُ ‏","","",""],[21259,21259,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَانُ بْنُ رِفَاعَةَ ‏ ‏حَدَّثَنِي ‏ ‏عَلِيُّ بْنُ يَزِيدَ ‏ ‏حَدَّثَنِي ‏ ‏الْقَاسِمُ ‏ ‏مَوْلَى ‏ ‏بَنِي يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ الْبَاهِلِيِّ ‏ ‏قَالَ ‏ ‏لَمَّا كَانَ فِي حَجَّةِ الْوَدَاعِ قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَوْمَئِذٍ مُرْدِفٌ ‏ ‏الْفَضْلَ بْنَ عَبَّاسٍ ‏ ‏عَلَى جَمَلٍ ‏ ‏آدَمَ ‏ ‏فَقَالَ يَا أَيُّهَا النَّاسُ ‏ ‏خُذُوا مِنْ الْعِلْمِ قَبْلَ أَنْ يُقْبَضَ الْعِلْمُ وَقَبْلَ أَنْ يُرْفَعَ الْعِلْمُ وَقَدْ كَانَ أَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَسْأَلُوا عَنْ أَشْيَاءَ إِنْ تُبْدَ لَكُمْ تَسُؤْكُمْ وَإِنْ تَسْأَلُوا عَنْهَا حِينَ يُنَزَّلُ الْقُرْآنُ تُبْدَ لَكُمْ عَفَا اللَّهُ عَنْهَا وَاللَّهُ غَفُورٌ حَلِيمٌ ‏} ‏قَالَ فَكُنَّا قَدْ كَرِهْنَا كَثِيرًا مِنْ مَسْأَلَتِهِ وَاتَّقَيْنَا ذَاكَ حِينَ أَنْزَلَ اللَّهُ عَلَى نَبِيِّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَأَتَيْنَا أَعْرَابِيًّا فَرَشَوْنَاهُ بِرِدَاءٍ قَالَ فَاعْتَمَّ بِهِ حَتَّى رَأَيْتُ حَاشِيَةَ الْبُرْدِ خَارِجَةً مِنْ حَاجِبِهِ الْأَيْمَنِ قَالَ ثُمَّ قُلْنَا لَهُ سَلْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَقَالَ لَهُ يَا نَبِيَّ اللَّهِ كَيْفَ يُرْفَعُ الْعِلْمُ مِنَّا وَبَيْنَ أَظْهُرِنَا الْمَصَاحِفُ وَقَدْ تَعَلَّمْنَا مَا فِيهَا وَعَلَّمْنَا نِسَاءَنَا وَذَرَارِيَّنَا وَخَدَمَنَا قَالَ فَرَفَعَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأْسَهُ وَقَدْ عَلَتْ وَجْهَهُ حُمْرَةٌ مِنْ الْغَضَبِ قَالَ فَقَالَ أَيْ ثَكِلَتْكَ أُمُّكَ هَذِهِ ‏ ‏الْيَهُودُ ‏ ‏وَالنَّصَارَى ‏ ‏بَيْنَ أَظْهُرِهِمْ الْمَصَاحِفُ لَمْ يُصْبِحُوا يَتَعَلَّقُوا بِحَرْفٍ مِمَّا جَاءَتْهُمْ بِهِ أَنْبِيَاؤُهُمْ أَلَا وَإِنَّ مِنْ ذَهَابِ الْعِلْمِ أَنْ يَذْهَبَ حَمَلَتُهُ ثَلَاثَ مِرَارٍ ‏","","",""],[21260,21260,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَانُ بْنُ رِفَاعَةَ ‏ ‏حَدَّثَنِي ‏ ‏عَلِيُّ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏سَرِيَّةٍ ‏ ‏مِنْ ‏ ‏سَرَايَاهُ ‏ ‏قَالَ فَمَرَّ رَجُلٌ بِغَارٍ فِيهِ شَيْءٌ مِنْ مَاءٍ قَالَ فَحَدَّثَ نَفْسَهُ بِأَنْ يُقِيمَ فِي ذَلِكَ الْغَارِ فَيَقُوتُهُ مَا كَانَ فِيهِ مِنْ مَاءٍ وَيُصِيبُ مَا حَوْلَهُ مِنْ الْبَقْلِ ‏ ‏وَيَتَخَلَّى مِنْ الدُّنْيَا ثُمَّ قَالَ لَوْ أَنِّي أَتَيْتُ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرْتُ ذَلِكَ لَهُ فَإِنْ أَذِنَ لِي فَعَلْتُ وَإِلَّا لَمْ أَفْعَلْ فَأَتَاهُ فَقَالَ يَا نَبِيَّ اللَّهِ إِنِّي مَرَرْتُ بِغَارٍ فِيهِ مَا يَقُوتُنِي مِنْ الْمَاءِ وَالْبَقْلِ فَحَدَّثَتْنِي نَفْسِي بِأَنْ أُقِيمَ فِيهِ ‏ ‏وَأَتَخَلَّى مِنْ الدُّنْيَا قَالَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي لَمْ أُبْعَثْ بِالْيَهُودِيَّةِ وَلَا بِالنَّصْرَانِيَّةِ وَلَكِنِّي بُعِثْتُ بِالْحَنِيفِيَّةِ السَّمْحَةِ وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ لَغَدْوَةٌ أَوْ رَوْحَةٌ فِي سَبِيلِ اللَّهِ خَيْرٌ مِنْ الدُّنْيَا وَمَا فِيهَا وَلَمُقَامُ أَحَدِكُمْ فِي الصَّفِّ خَيْرٌ مِنْ صَلَاتِهِ سِتِّينَ سَنَةً ‏","","",""],[21261,21261,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَانُ بْنُ رِفَاعَةَ ‏ ‏حَدَّثَنِي ‏ ‏عَلِيُّ بْنُ يَزِيدَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْقَاسِمَ أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏مَرَّ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي يَوْمٍ شَدِيدِ الْحَرِّ نَحْوَ ‏ ‏بَقِيعِ الْغَرْقَدِ ‏ ‏قَالَ فَكَانَ النَّاسُ يَمْشُونَ خَلْفَهُ قَالَ فَلَمَّا سَمِعَ صَوْتَ النِّعَالِ وَقَرَ ذَلِكَ فِي نَفْسِهِ فَجَلَسَ حَتَّى قَدَّمَهُمْ أَمَامَهُ لِئَلَّا يَقَعَ فِي نَفْسِهِ شَيْءٌ مِنْ الْكِبْرِ فَلَمَّا مَرَّ ‏ ‏بِبَقِيعِ الْغَرْقَدِ ‏ ‏إِذَا بِقَبْرَيْنِ قَدْ دَفَنُوا فِيهِمَا رَجُلَيْنِ قَالَ فَوَقَفَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَنْ دَفَنْتُمْ هَاهُنَا الْيَوْمَ قَالُوا يَا نَبِيَّ اللَّهِ فُلَانٌ وَفُلَانٌ قَالَ ‏ ‏إِنَّهُمَا لَيُعَذَّبَانِ الْآنَ وَيُفْتَنَانِ فِي قَبْرَيْهِمَا قَالُوا يَا رَسُولَ اللَّهِ فِيمَ ذَاكَ قَالَ أَمَّا أَحَدُهُمَا فَكَانَ لَا يَتَنَزَّهُ مِنْ الْبَوْلِ وَأَمَّا الْآخَرُ فَكَانَ يَمْشِي بِالنَّمِيمَةِ وَأَخَذَ جَرِيدَةً رَطْبَةً فَشَقَّهَا ثُمَّ جَعَلَهَا عَلَى الْقَبْرَيْنِ قَالُوا يَا نَبِيَّ اللَّهِ وَلِمَ فَعَلْتَ قَالَ لِيُخَفَّفَنَّ عَنْهُمَا قَالُوا يَا نَبِيَّ اللَّهِ وَحَتَّى مَتَى يُعَذِّبُهُمَا اللَّهُ قَالَ غَيْبٌ لَا يَعْلَمُهُ إِلَّا اللَّهُ قَالَ وَلَوْلَا تَمَزُّعُ قُلُوبِكُمْ أَوْ تَزَيُّدُكُمْ فِي الْحَدِيثِ لَسَمِعْتُمْ مَا أَسْمَعُ ‏","","",""],[21262,21262,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَانُ بْنُ رِفَاعَةَ ‏ ‏حَدَّثَنِي ‏ ‏عَلِيُّ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏جَلَسْنَا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَّرَنَا وَرَقَّقَنَا فَبَكَى ‏ ‏سَعْدُ بْنُ أَبِي وَقَّاصٍ ‏ ‏فَأَكْثَرَ الْبُكَاءَ فَقَالَ يَا لَيْتَنِي مِتُّ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏سَعْدُ ‏ ‏أَعِنْدِي ‏ ‏تَتَمَنَّى الْمَوْتَ فَرَدَّدَ ذَلِكَ ثَلَاثَ مَرَّاتٍ ثُمَّ قَالَ يَا ‏ ‏سَعْدُ ‏ ‏إِنْ كُنْتَ خُلِقْتَ لِلْجَنَّةِ فَمَا طَالَ عُمْرُكَ أَوْ حَسُنَ مِنْ عَمَلِكَ فَهُوَ خَيْرٌ لَكَ ‏","","",""],[21263,21263,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏حَدَّثَنَا ‏ ‏شُرَحْبِيلُ بْنُ مُسْلِمٍ الْخَوْلَانِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا أُمَامَةَ الْبَاهِلِيَّ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي خُطْبَتِهِ عَامَّ حَجَّةِ الْوَدَاعِ ‏ ‏إِنَّ اللَّهَ قَدْ أَعْطَى كُلَّ ذِي حَقٍّ حَقَّهُ فَلَا وَصِيَّةَ لِوَارِثٍ وَالْوَلَدُ ‏ ‏لِلْفِرَاشِ ‏ ‏وَلِلْعَاهِرِ ‏ ‏الْحَجَرُ ‏ ‏وَحِسَابُهُمْ عَلَى اللَّهِ وَمَنْ ادَّعَى إِلَى غَيْرِ أَبِيهِ أَوْ انْتَمَى إِلَى غَيْرِ مَوَالِيهِ فَعَلَيْهِ لَعْنَةُ اللَّهِ التَّابِعَةُ إِلَى يَوْمِ الْقِيَامَةِ لَا تُنْفِقُ الْمَرْأَةُ شَيْئًا مِنْ بَيْتِهَا إِلَّا بِإِذْنِ زَوْجِهَا فَقِيلَ يَا رَسُولَ اللَّهِ وَلَا الطَّعَامَ قَالَ ذَلِكَ أَفْضَلُ أَمْوَالِنَا قَالَ ثُمَّ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعَارِيَةُ مُؤَدَّاةٌ وَالْمِنْحَةُ مَرْدُودَةٌ وَالدَّيْنَ مَقْضِيٌّ وَالزَّعِيمُ ‏ ‏غَارِمٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ مَعِينٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏شُرَحْبِيلَ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الزَّعِيمُ غَارِمٌ ‏","","",""],[21264,21264,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏حَرِيزٌ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمُ بْنُ عَامِرٍ الْخَبَائِرِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا أُمَامَةَ الْبَاهِلِيَّ ‏ ‏يَقُولُ ‏ ‏مَا كَانَ يَفْضُلُ عَنْ أَهْلِ بَيْتِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خُبْزُ الشَّعِيرِ ‏","","",""],[21265,21265,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏حَرِيزُ بْنُ عُثْمَانَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَيْسَرَةَ الْحَضْرَمِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا أُمَامَةَ ‏ ‏يَقُولُ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيَدْخُلَنَّ الْجَنَّةَ بِشَفَاعَةِ الرَّجُلِ الْوَاحِدِ لَيْسَ بِنَبِيٍّ مِثْلُ الْحَيَّيْنِ أَوْ أَحَدِ الْحَيَّيْنِ ‏ ‏رَبِيعَةَ ‏ ‏وَمُضَرَ ‏ ‏فَقَالَ قَائِلٌ إِنَّمَا ‏ ‏رَبِيعَةُ ‏ ‏مِنْ ‏ ‏مُضَرَ ‏ ‏قَالَ إِنَّمَا أَقُولُ مَا أَقُولُ ‏","","",""],[21266,21266,"","","‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ بْنُ شُرَيْحٍ ‏ ‏حَدَّثَنَا ‏ ‏بَقِيَّةُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ زِيَادٍ الْأَلْهَانِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا أُمَامَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُوصِي بِالْجَارِ حَتَّى ظَنَنْتُ أَنَّهُ سَيُوَرِّثُهُ ‏","","",""],[21267,21267,"","","‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةٌ ‏ ‏حَدَّثَنَا ‏ ‏بَقِيَّةُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ زِيَادٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو رَاشِدٍ الْحُبْرَانِيُّ ‏ ‏قَالَ ‏ ‏أَخَذَ بِيَدِي ‏ ‏أَبُو أُمَامَةَ الْبَاهِلِيُّ ‏ ‏قَالَ ‏ ‏أَخَذَ بِيَدِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لِي يَا ‏ ‏أَبَا أُمَامَةَ ‏ ‏إِنَّ مِنْ الْمُؤْمِنِينَ مَنْ يَلِينُ لِي قَلْبُهُ ‏","","",""],[21268,21268,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏لُقْمَانَ بْنِ عَامِرٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَا مِنْ رَجُلٍ يَلِي أَمْرَ عَشَرَةٍ فَمَا فَوْقَ ذَلِكَ إِلَّا أَتَى اللَّهَ عَزَّ وَجَلَّ مَغْلُولًا يَوْمَ الْقِيَامَةِ يَدُهُ إِلَى عُنُقِهِ فَكَّهُ بِرُّهُ أَوْ أَوْبَقَهُ إِثْمُهُ أَوَّلُهَا مَلَامَةٌ وَأَوْسَطُهَا نَدَامَةٌ وَآخِرُهَا خِزْيٌ يَوْمَ الْقِيَامَةِ ‏","","",""],[21269,21269,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏السَّرِيُّ بْنُ يَنْعُمَ ‏ ‏حَدَّثَنِي ‏ ‏عَامِرُ بْنُ جَشِيبٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏دُعِينَا إِلَى ‏ ‏وَلِيمَةٍ ‏ ‏وَهُوَ مَعَنَا فَلَمَّا شَبِعَ مِنْ الطَّعَامِ قَامَ فَقَالَ أَمَا إِنِّي لَسْتُ أَقُومُ مَقَامِي هَذَا خَطِيبًا كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا شَبِعَ مِنْ الطَّعَامِ قَالَ ‏ ‏الْحَمْدُ لِلَّهِ كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ غَيْرَ ‏ ‏مَكْفِيٍّ ‏ ‏وَلَا مُسْتَغْنًى عَنْهُ ‏","","",""],[21270,21270,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ اللَّهِ يَعْنِي ابْنَ أَبِي مَرْيَمَ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ عُبَيْدٍ الرَّحَبِيِّ ‏ ‏أَنَّ ‏ ‏أَبَا أُمَامَةَ ‏ ‏دَخَلَ عَلَى ‏ ‏خَالِدِ بْنِ يَزِيدَ ‏ ‏فَأَلْقَى لَهُ وَسَادَةً فَظَنَّ ‏ ‏أَبُو أُمَامَةَ ‏ ‏أَنَّهَا حَرِيرٌ فَتَنَحَّى يَمْشِي ‏ ‏الْقَهْقَرَى ‏ ‏حَتَّى بَلَغَ آخِرَ ‏ ‏السِّمَاطِ ‏ ‏وَخَالِدٌ ‏ ‏يُكَلِّمُ رَجُلًا ثُمَّ الْتَفَتَ إِلَى ‏ ‏أَبِي أُمَامَةَ ‏ ‏فَقَالَ لَهُ يَا أَخِي مَا ظَنَنْتَ أَظَنَنْتَ أَنَّهَا حَرِيرٌ قَالَ ‏ ‏أَبُو أُمَامَةَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَسْتَمْتِعُ بِالْحَرِيرِ مَنْ يَرْجُو أَيَّامَ اللَّهِ فَقَالَ لَهُ ‏ ‏خَالِدٌ ‏ ‏يَا ‏ ‏أَبَا أُمَامَةَ ‏ ‏أَنْتَ سَمِعْتَ هَذَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ اللَّهُمَّ ‏ ‏غُفْرًا أَنْتَ سَمِعْتَ هَذَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَلْ كُنَّا فِي قَوْمٍ مَا كَذَبُونَا وَلَا كُذِّبْنَا ‏","","",""],[21271,21271,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زِيَادٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏وَعَدَنِي رَبِّي عَزَّ وَجَلَّ أَنْ يُدْخِلَ الْجَنَّةَ مِنْ أُمَّتِي سَبْعِينَ أَلْفًا بِغَيْرِ حِسَابٍ وَلَا عَذَابٍ مَعَ كُلِّ أَلْفٍ سَبْعُونَ أَلْفًا وَثَلَاثَ ‏ ‏حَثَيَاتٍ ‏ ‏مِنْ ‏ ‏حَثَيَاتِ ‏ ‏رَبِّي عَزَّ وَجَلَّ ‏","","",""],[21272,21272,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ الْحَارِثِ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ مَشَى إِلَى صَلَاةٍ مَكْتُوبَةٍ وَهُوَ مُتَطَهِّرٌ كَانَ لَهُ كَأَجْرِ الْحَاجِّ الْمُحْرِمِ وَمَنْ مَشَى إِلَى سُبْحَةِ الضُّحَى كَانَ لَهُ كَأَجْرِ الْمُعْتَمِرِ وَصَلَاةٌ عَلَى إِثْرِ صَلَاةٍ لَا لَغْوَ بَيْنَهُمَا كِتَابٌ فِي ‏ ‏عِلِّيِّينَ ‏ ‏و قَالَ ‏ ‏أَبُو أُمَامَةَ ‏ ‏الْغُدُوُّ ‏ ‏وَالرَّوَاحُ ‏ ‏إِلَى هَذِهِ الْمَسَاجِدِ مِنْ الْجِهَادِ فِي سَبِيلِ اللَّهِ ‏","","",""],[21273,21273,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ عَبْدِ رَبِّهِ ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ أَبِي الْعَاتِكَةِ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏عَمَّنْ ‏ ‏رَأَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَاحَ إِلَى ‏ ‏مِنًى ‏ ‏يَوْمَ التَّرْوِيَةِ وَإِلَى جَانِبِهِ ‏ ‏بِلَالٌ ‏ ‏بِيَدِهِ عُودٌ عَلَيْهِ ثَوْبٌ يُظِلُّ بِهِ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[21274,21274,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏بَكْرُ بْنُ خُنَيْسٍ ‏ ‏عَنْ ‏ ‏لَيْثِ بْنِ أَبِي سُلَيْمٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَرْطَاةَ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أُذِنَ لِعَبْدٍ فِي شَيْءٍ أَفْضَلَ مِنْ رَكْعَتَيْنِ يُصَلِّيهِمَا وَإِنَّ الْبِرَّ لَيُذَرُّ فَوْقَ رَأْسِ الْعَبْدِ مَا دَامَ فِي صَلَاتِهِ وَمَا تَقَرَّبَ الْعِبَادُ إِلَى اللَّهِ تَعَالَى بِمِثْلِ مَا خَرَجَ مِنْهُ ‏ ‏يَعْنِي الْقُرْآنَ ‏","","",""],[21275,21275,"","","‏ ‏حَدَّثَنَا ‏ ‏الْهَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏الْفَرَجُ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ أَبِي عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ بَعَثَنِي رَحْمَةً لِلْعَالَمِينَ وَهُدًى لِلْعَالَمِينَ وَأَمَرَنِي رَبِّي عَزَّ وَجَلَّ بِمَحْقِ الْمَعَازِفِ وَالْمَزَامِيرِ وَالْأَوْثَانِ وَالصُّلُبِ وَأَمْرِ الْجَاهِلِيَّةِ وَحَلَفَ رَبِّي عَزَّ وَجَلَّ بِعِزَّتِهِ ‏ ‏لَا يَشْرَبُ عَبْدٌ مِنْ عَبِيدِي جَرْعَةً مِنْ خَمْرٍ إِلَّا سَقَيْتُهُ مِنْ الصَّدِيدِ مِثْلَهَا يَوْمَ الْقِيَامَةِ مَغْفُورًا لَهُ أَوْ مُعَذَّبًا وَلَا ‏ ‏يَسْقِيهَا صَبِيًّا صَغِيرًا ضَعِيفًا مُسْلِمًا إِلَّا سَقَيْتُهُ مِنْ الصَّدِيدِ مِثْلَهَا يَوْمَ الْقِيَامَةِ مَغْفُورًا لَهُ أَوْ مُعَذَّبًا وَلَا يَتْرُكُهَا مِنْ مَخَافَتِي إِلَّا سَقَيْتُهُ مِنْ حِيَاضِ الْقُدُسِ يَوْمَ الْقِيَامَةِ وَلَا يَحِلُّ بَيْعُهُنَّ وَلَا شِرَاؤُهُنَّ وَلَا تَعْلِيمُهُنَّ وَلَا تِجَارَةٌ فِيهِنَّ وَثَمَنُهُنَّ حَرَامٌ ‏ ‏يَعْنِي الضَّارِبَاتِ ‏","","",""],[21276,21276,"","","‏ ‏حَدَّثَنَا ‏ ‏حُجَيْنُ بْنُ الْمُثَنَّى ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ يَعْنِي ابْنَ أَبِي سَلَمَةَ الْمَاجِشُونَ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَطِيَّةَ بْنِ دِلَافٍ الْمُزَنِيِّ ‏ ‏لَا أَعْلَمُهُ إِلَّا ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏يَرْفَعُهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تَخْرُجُ الدَّابَّةُ فَتَسِمُ النَّاسَ عَلَى خَرَاطِيمِهِمْ ثُمَّ يَغْمُرُونَ فِيكُمْ حَتَّى يَشْتَرِيَ الرَّجُلُ الْبَعِيرَ فَيَقُولُ مِمَّنْ اشْتَرَيْتَهُ فَيَقُولُ اشْتَرَيْتُهُ مِنْ أَحَدِ ‏ ‏الْمُخَطَّمِينَ ‏ ‏و قَالَ ‏ ‏يُونُسُ يَعْنِي ابْنَ مُحَمَّدٍ ‏ ‏ثُمَّ يَغْمُرُونَ فِيكُمْ وَلَمْ يَشُكَّ قَالَ فَرَفَعَهُ ‏","","",""],[21277,21277,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ الْمُبَارَكِ ‏ ‏أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ أَيُّوبَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ زَحْرٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَائِدُ ‏ ‏الْمَرِيضِ يَخُوضُ فِي الرَّحْمَةِ وَوَضَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدَهُ عَلَى وَرِكِهِ ثُمَّ قَالَ هَكَذَا مُقْبِلًا وَمُدْبِرًا وَإِذَا جَلَسَ عِنْدَهُ غَمَرَتْهُ الرَّحْمَةُ ‏","","",""],[21278,21278,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏سِنَانِ بْنِ رَبِيعَةَ ‏ ‏عَنْ ‏ ‏شَهْرٍ يَعْنِي ابْنَ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ فَمَضْمَضَ ثَلَاثًا وَاسْتَنْشَقَ ثَلَاثًا وَغَسَلَ وَجْهَهُ وَكَانَ يَمْسَحُ ‏ ‏الْمَاقَيْنِ ‏ ‏مِنْ الْعَيْنِ قَالَ وَكَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْسَحُ رَأْسَهُ مَرَّةً وَاحِدَةً وَكَانَ يَقُولُ الْأُذُنَانِ مِنْ الرَّأْسِ ‏","","",""],[21279,21279,"","","‏ ‏حَدَّثَنَا ‏ ‏زِيَادُ بْنُ عَبْدِ اللَّهِ الْبَكَّائِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏جَاءَتْ امْرَأَةٌ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَعَهَا ابْنَانِ لَهَا وَهِيَ حَامِلٌ فَمَا سَأَلَتْهُ يَوْمَئِذٍ إِلَّا أَعْطَاهَا ثُمَّ قَالَ ‏ ‏حَامِلَاتٌ وَالِدَاتٌ رَحِيمَاتٌ لَوْلَا مَا يَأْتِينَ إِلَى أَزْوَاجِهِنَّ دَخَلْنَ الْجَنَّةَ ‏","","",""],[21280,21280,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏وَغَيْرُهُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏حَسَّانَ بْنِ عَطِيَّةَ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ الْبَاهِلِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْحَيَاءُ ‏ ‏وَالْعِيُّ ‏ ‏شُعْبَتَانِ مِنْ الْإِيمَانِ ‏ ‏وَالْبَذَاءُ ‏ ‏وَالْبَيَانُ ‏ ‏شُعْبَتَانِ مِنْ النِّفَاقِ ‏","","",""],[21281,21281,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏عُمَارَةُ يَعْنِي ابْنَ زَاذَانَ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو غَالِبٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُوتِرُ ‏ ‏بِتِسْعٍ حَتَّى إِذَا بَدَّنَ وَكَثُرَ لَحْمُهُ ‏ ‏أَوْتَرَ ‏ ‏بِسَبْعٍ وَصَلَّى رَكْعَتَيْنِ وَهُوَ جَالِسٌ فَقَرَأَ ‏ ‏بِإِذَا زُلْزِلَتْ ‏ ‏وَقُلْ يَا أَيُّهَا الْكَافِرُونَ ‏","","",""],[21282,21282,"","","‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ عِيَاضٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏صَفْوَانَ بْنَ سُلَيْمٍ ‏ ‏يَقُولُ ‏ ‏دَخَلَ ‏ ‏أَبُو أُمَامَةَ الْبَاهِلِيُّ ‏ ‏دِمَشْقَ ‏ ‏فَرَأَى رُءُوسَ ‏ ‏حَرُورَاءَ ‏ ‏قَدْ نُصِبَتْ فَقَالَ ‏ ‏كِلَابُ النَّارِ كِلَابُ النَّارِ ثَلَاثًا شَرُّ قَتْلَى تَحْتَ ظِلِّ السَّمَاءِ خَيْرُ قَتْلَى مَنْ قَتَلُوا ثُمَّ بَكَى فَقَامَ إِلَيْهِ رَجُلٌ فَقَالَ يَا ‏ ‏أَبَا أُمَامَةَ ‏ ‏هَذَا الَّذِي تَقُولُ مِنْ رَأْيِكَ أَمْ سَمِعْتَهُ قَالَ إِنِّي إِذًا لَجَرِيءٌ كَيْفَ أَقُولُ هَذَا عَنْ رَأْيٍ قَالَ قَدْ سَمِعْتُهُ غَيْرَ مَرَّةٍ وَلَا مَرَّتَيْنِ قَالَ فَمَا ‏ ‏يُبْكِيكَ قَالَ أَبْكِي لِخُرُوجِهِمْ مِنْ الْإِسْلَامِ هَؤُلَاءِ الَّذِينَ تَفَرَّقُوا وَاتَّخَذُوا دِينَهُمْ شِيَعًا ‏","","",""],[21283,21283,"","","‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏ثَوْرِ بْنِ يَزِيدَ ‏ ‏عَنِ ‏ ‏الْوَلِيدِ بْنِ أَبِي مَالِكٍ ‏ ‏قَالَ ‏ ‏دَخَلَ رَجُلٌ الْمَسْجِدَ فَصَلَّى فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا رَجُلٌ ‏ ‏يَتَصَدَّقُ ‏ ‏عَلَى هَذَا فَيُصَلِّيَ مَعَهُ قَالَ فَقَامَ رَجُلٌ فَصَلَّى مَعَهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذَانِ جَمَاعَةٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَيُّوبَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ زَحْرٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَحْوَهُ وَقَالَ هَذَانِ جَمَاعَةٌ ‏","","",""],[21284,21284,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏قَالَ ‏ ‏الْحَسَنُ بْنُ صَالِحٍ ‏ ‏حَدَّثَنَا عَنْ ‏ ‏أَبِي الْمُهَلَّبِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ زَحْرٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ يَزِيدَ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ بَدَأَ بِالسَّلَامِ فَهُوَ أَوْلَى بِاللَّهِ عَزَّ وَجَلَّ وَبِرَسُولِهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[21285,21285,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ أَبِي عِمْرَانَ ‏ ‏عَمَّنْ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أَبِي أُمَامَةَ الْبَاهِلِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَرْبَعٌ ‏ ‏تَجْرِي عَلَيْهِمْ أُجُورُهُمْ بَعْدَ الْمَوْتِ رَجُلٌ مَاتَ مُرَابِطًا فِي سَبِيلِ اللَّهِ وَرَجُلٌ عَلَّمَ عِلْمًا فَأَجْرُهُ يَجْرِي عَلَيْهِ مَا عَمِلَ بِهِ وَرَجُلٌ أَجْرَى ‏ ‏صَدَقَةً ‏ ‏فَأَجْرُهَا يَجْرِي عَلَيْهِ مَا جَرَتْ عَلَيْهِ وَرَجُلٌ تَرَكَ وَلَدًا صَالِحًا يَدْعُو لَهُ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ أَبِي عِمْرَانَ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَهُ إِلَّا أَنَّهُ قَالَ وَمَنْ عَلَّمَ عِلْمًا أُجْرِيَ لَهُ مِثْلُ مَا عَلَّمَ ‏","","",""],[21286,21286,"","","‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي بِخَطِّ يَدِهِ ‏ ‏حَدَّثَنِي ‏ ‏مَهْدِيُّ بْنُ جَعْفَرٍ الرَّمْلِيُّ ‏ ‏حَدَّثَنَا ‏ ‏ضَمْرَةُ ‏ ‏عَنِ ‏ ‏الشَّيْبَانِيِّ وَاسْمُهُ يَحْيَى بْنُ أَبِي عَمْرٍو ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ عَبْدِ اللَّهِ الْحَضْرَمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَزَالُ طَائِفَةٌ مِنْ أُمَّتِي عَلَى الْحَقِّ ظَاهِرِينَ لَعَدُوِّهِمْ قَاهِرِينَ لَا يَضُرُّهُمْ مَنْ خَالَفَهُمْ إِلَّا مَا أَصَابَهُمْ مِنْ لَأْوَاءَ حَتَّى يَأْتِيَهُمْ أَمْرُ اللَّهِ وَهُمْ كَذَلِكَ قَالُوا يَا رَسُولَ اللَّهِ وَأَيْنَ هُمْ قَالَ ‏ ‏بِبَيْتِ الْمَقْدِسِ ‏ ‏وَأَكْنَافِ ‏ ‏بَيْتِ الْمَقْدِسِ ‏","","",""],[21287,21287,"","","‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي بِخَطِّ يَدِهِ ‏ ‏وَأَظُنُّ أَنِّي قَدْ ‏ ‏سَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏الْحَكَمِ ‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏مُطَّرِحِ بْنِ يَزِيدَ الْكِنَانِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ زَحْرٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏أَنَّ رَجُلًا سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّ ‏ ‏الصَّدَقَةِ ‏ ‏أَفْضَلُ قَالَ ‏ ‏ظِلُّ ‏ ‏فُسْطَاطٍ ‏ ‏فِي سَبِيلِ اللَّهِ أَوْ خِدْمَةُ خَادِمٍ فِي سَبِيلِ اللَّهِ أَوْ ‏ ‏طَرُوقَةُ ‏ ‏فَحْلٍ ‏ ‏فِي سَبِيلِ اللَّهِ ‏ ‏آخِرُ حَدِيثِ ‏ ‏أَبِي أُمَامَةَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏","","",""],[21288,21288,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ ‏ ‏عَنْ ‏ ‏مَعْبَدِ بْنِ كَعْبٍ السَّلَمِيِّ ‏ ‏عَنْ ‏ ‏أَخِيهِ ‏ ‏عَبْدِ اللَّهِ بْنِ كَعْبٍ ‏ ‏عَنْ ‏ ‏أَبِي أُمَامَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ اقْتَطَعَ حَقَّ امْرِئٍ مُسْلِمٍ بِيَمِينِهِ فَقَدْ أَوْجَبَ اللَّهُ لَهُ النَّارَ وَحَرَّمَ عَلَيْهِ الْجَنَّةَ فَقَالَ لَهُ رَجُلٌ وَإِنْ كَانَ شَيْئًا يَسِيرًا يَا رَسُولَ اللَّهِ قَالَ وَإِنْ كَانَ قَضِيبًا مِنْ ‏ ‏أَرَاكٍ ‏","","",""],[21289,21289,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏زُهَيْرٍ يَعْنِي ابْنَ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏صَالِحٍ يَعْنِي ابْنَ كَيْسَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي أُمَامَةَ الْحَارِثِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَذَاذَةُ مِنْ الْإِيمَانِ ‏","","",""],[21290,21290,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ الْمُقْرِي عَبْدُ اللَّهِ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو صَخْرٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏مَكْحُولًا ‏ ‏يَقُولُ حَدَّثَنِي ‏ ‏أَبُو هِنْدٍ الدَّارِيُّ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ قَامَ مَقَامَ ‏ ‏رِيَاءٍ ‏ ‏وَسُمْعَةٍ ‏ ‏رَايَا ‏ ‏اللَّهُ تَعَالَى بِهِ يَوْمَ الْقِيَامَةِ وَسَمَّعَ ‏","","",""],[21291,21291,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ مُصْعَبٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏سَيُفْتَحُ عَلَيْكُمْ ‏ ‏الشَّامُ ‏ ‏وَإِنَّ بِهَا مَكَانًا يُقَالُ لَهُ ‏ ‏الْغُوطَةُ ‏ ‏يَعْنِي ‏ ‏دِمَشْقَ ‏ ‏مِنْ خَيْرِ مَنَازِلِ الْمُسْلِمِينَ ‏ ‏يَعْنِي فِي ‏ ‏الْمَلَاحِمِ ‏","","",""],[21292,21292,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَمْزَةَ ‏ ‏عَنْ ‏ ‏عَطَاءٍ الْخُرَاسَانِيِّ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ مُحَيْرِيزٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ السَّعْدِيِّ ‏ ‏رَجُلٍ مِنْ ‏ ‏بَنِي مَالِكِ بْنِ حَنْبَلٍ ‏ ‏أَنَّهُ قَدِمَ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي نَاسٍ مِنْ أَصْحَابِهِ فَقَالُوا لَهُ احْفَظْ رِحَالَنَا ثُمَّ تَدْخُلُ وَكَانَ أَصْغَرَ الْقَوْمِ فَقَضَى لَهُمْ حَاجَتَهُمْ ثُمَّ قَالُوا لَهُ ادْخُلْ فَدَخَلَ فَقَالَ حَاجَتُكَ قَالَ حَاجَتِي تُحَدِّثُنِي أَنْقَضَتْ الْهِجْرَةُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَاجَتُكَ خَيْرٌ مِنْ حَوَائِجِهِمْ لَا تَنْقَطِعُ الْهِجْرَةُ مَا قُوتِلَ الْعَدُوُّ ‏","","",""],[21293,21293,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏عَنْ ‏ ‏أَبِي السَّلِيلِ ‏ ‏عَنْ ‏ ‏عَجُوزٍ مِنْ بَنِي نُمَيْرٍ ‏ ‏أَنَّهَا ‏ ‏سَمِعَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يُصَلِّي بِالنَّاسِ وَوَجْهُهُ إِلَى ‏ ‏الْبَيْتِ ‏ ‏قَالَ فَحَفِظَتْ مِنْهُ ‏ ‏رَبِّ اغْفِرْ لِي خَطَايَايَ وَجَهْلِي ‏","","",""],[21294,21294,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْمَاعِيلَ بْنِ أَبِي فُدَيْكٍ ‏ ‏حَدَّثَنَا ‏ ‏الضَّحَّاكُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَمَّنْ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏عَمْرِو بْنِ عَبْدِ اللَّهِ بْنِ كَعْبٍ ‏ ‏عَنِ ‏ ‏الْمَرْأَةِ مِنَ الْمُبَايِعَاتِ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏جَاءَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَعَهُ أَصْحَابُهُ فِي ‏ ‏بَنِي سَلِمَةَ ‏ ‏فَقَرَّبْنَا إِلَيْهِ طَعَامًا فَأَكَلَ وَمَعَهُ أَصْحَابُهُ ثُمَّ قَرَّبْنَا إِلَيْهِ وَضُوءًا فَتَوَضَّأَ ثُمَّ أَقْبَلَ عَلَى أَصْحَابِهِ فَقَالَ أَلَا أُخْبِرُكُمْ بِمُكَفِّرَاتِ الْخَطَايَا قَالُوا بَلَى قَالَ ‏ ‏إِسْبَاغُ الْوُضُوءِ عَلَى ‏ ‏الْمَكَارِهِ ‏ ‏وَكَثْرَةُ الْخُطَى إِلَى الْمَسَاجِدِ وَانْتِظَارُ الصَّلَاةِ بَعْدَ الصَّلَاةِ ‏","","",""],[21295,21295,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ عَمْرِو بْنِ الْأَحْوَصِ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏أَنَّهَا شَهِدَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِنْدَ جَمْرَةِ ‏ ‏الْعَقَبَةِ ‏ ‏وَالنَّاسُ يَرْمُونَ فَقَالَ يَا أَيُّهَا النَّاسُ ‏ ‏لَا تَقْتُلُوا ‏ ‏أَوْ لَا تُهْلِكُوا ‏ ‏أَنْفُسَكُمْ وَارْمُوا الْجَمْرَةَ أَوْ الْجَمَرَاتِ بِمِثْلِ حَصَى ‏ ‏الْخَذْفِ ‏ ‏وَأَشَارَ ‏ ‏شُعْبَةُ ‏ ‏بِطَرَفِ إِصْبَعِهِ السَّبَّابَةِ ‏","","",""],[21296,21296,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ يَعْنِي الْمُقْرِي ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ يَعْنِي ابْنَ أَبِي أَيُّوبَ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو عِيسَى الْخُرَاسَانِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْقَاسِمِ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏جَارَةٌ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهَا ‏ ‏كَانَتْ تَسْمَعُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ عِنْدَ طُلُوعِ الْفَجْرِ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ وَمِنْ فِتْنَةِ الْقَبْرِ ‏ ‏قَالَ ‏ ‏أَبُو عِيسَى ‏ ‏فَقُلْتُ ‏ ‏لِعَبْدِ اللَّهِ ‏ ‏أَرَأَيْتَ إِنْ جَمَعَهُمَا إِنْسَانٌ قَالَ ‏ ‏فَقَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا قَالَ ‏","","",""],[21297,21297,"","","‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ الْوَلِيدِ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏سَعِيدٍ الْجُرَيْرِيِّ ‏ ‏عَنِ ‏ ‏السَّعْدِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَوْ ‏ ‏عَمِّهِ ‏ ‏قَالَ ‏ ‏رَمَقْتُ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي صَلَاتِهِ فَكَانَ ‏ ‏يَمْكُثُ فِي رُكُوعِهِ وَسُجُودِهِ قَدْرَ مَا يَقُولُ سُبْحَانَ اللَّهِ وَبِحَمْدِهِ ثَلَاثًا ‏","","",""],[21298,21298,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو جَعْفَرٍ ‏ ‏عَنْ ‏ ‏يَحْيَى الْبَكَّاءِ ‏ ‏عَنْ ‏ ‏أَبِي رَافِعٍ ‏ ‏قَالَ ‏ ‏كُنْتُ ‏ ‏أَصُوغُ ‏ ‏لِأَزْوَاجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَحَدَّثْنَنِي أَنَّهُنَّ لَسَمِعْنَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الذَّهَبُ بِالذَّهَبِ وَالْفِضَّةُ بِالْفِضَّةِ وَزْنًا بِوَزْنٍ فَمَنْ زَادَ ‏ ‏أَوْ اسْتَزَادَ ‏ ‏فَقَدْ أَرْبَى ‏","","",""],[21299,21299,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏خَالِدُ بْنُ عَمْرٍو ‏ ‏عَنِ ‏ ‏ابْنِ حَرْمَلَةَ ‏ ‏عَنْ ‏ ‏خَالَتِهِ ‏ ‏قَالَتْ ‏ ‏خَطَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ عَاصِبٌ إِصْبَعَهُ مِنْ لَدْغَةِ عَقْرَبٍ فَقَالَ ‏ ‏إِنَّكُمْ تَقُولُونَ لَا عَدُوَّ وَإِنَّكُمْ لَا تَزَالُونَ تُقَاتِلُونَ عَدُوًّا حَتَّى يَأْتِيَ ‏ ‏يَأْجُوجُ ‏ ‏وَمَأْجُوجُ ‏ ‏عِرَاضُ الْوُجُوهِ صِغَارُ الْعُيُونِ ‏ ‏شُهْبُ ‏ ‏الشِّعَافِ ‏ ‏مِنْ كُلِّ ‏ ‏حَدَبٍ ‏ ‏يَنْسِلُونَ كَأَنَّ وُجُوهَهُمْ ‏ ‏الْمَجَانُّ ‏ ‏الْمُطْرَقَةُ ‏","","",""],[21300,21300,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ بْنُ عَبْدِ الْوَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏رَافِعُ بْنُ سَلَمَةَ الْأَشْجَعِيُّ ‏ ‏حَدَّثَنِي ‏ ‏حَشْرَجُ بْنُ زِيَادٍ الْأَشْجَعِيُّ ‏ ‏عَنْ ‏ ‏جَدَّتِهِ أُمِّ أَبِيهِ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏خَرَجْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَزَاةِ ‏ ‏خَيْبَرَ ‏ ‏وَأَنَا سَادِسُ سِتِّ نِسْوَةٍ فَبَلَغَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ مَعَهُ نِسَاءً فَأَرْسَلَ إِلَيْنَا فَقَالَ ‏ ‏مَا أَخْرَجَكُنَّ وَبِأَمْرِ مَنْ خَرَجْتُنَّ فَقُلْنَا خَرَجْنَا نُنَاوِلُ السِّهَامَ وَنَسْقِي النَّاسَ السَّوِيقَ وَمَعَنَا مَا نُدَاوِي بِهِ الْجَرْحَى وَنَغْزِلُ الشَّعْرَ وَنُعِينُ بِهِ فِي سَبِيلِ اللَّهِ قَالَ قُمْنَ فَانْصَرِفْنَ فَلَمَّا فَتَحَ اللَّهُ عَلَيْهِ ‏ ‏خَيْبَرَ ‏ ‏أَخْرَجَ لَنَا سِهَامًا كَسِهَامِ الرَّجُلِ قُلْتُ يَا جَدَّةُ مَا أَخْرَجَ لَكُنَّ قَالَتْ تَمْرًا ‏","","",""],[21301,21301,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عِمْرَانَ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ عَبْدِ اللَّهِ ‏ ‏وَكَانَ عَامِلًا عَلَى ‏ ‏تَوَّجَ ‏ ‏وَأَثْنَى عَلَيْهِ خَيْرًا ‏ ‏عَنْ ‏ ‏بَعْضِ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ نَامَ عَلَى ‏ ‏إِجَّارٍ ‏ ‏لَيْسَ عَلَيْهِ مَا يَدْفَعُ قَدَمَيْهِ فَخَرَّ فَقَدْ بَرِئَتْ مِنْهُ الذِّمَّةُ وَمَنْ رَكِبَ الْبَحْرَ إِذَا ‏ ‏ارْتَجَّ ‏ ‏فَقَدْ بَرِئَتْ مِنْهُ الذِّمَّةُ ‏","","",""],[21302,21302,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْحُرُّ بْنُ الصَّيَّاحِ ‏ ‏قَالَ ‏ ‏سُرَيْجٌ ‏ ‏عَنِ ‏ ‏الْحُرِّ ‏ ‏عَنْ ‏ ‏هُنَيْدَةَ بْنِ خَالِدٍ ‏ ‏عَنِ ‏ ‏امْرَأَتِهِ ‏ ‏عَنْ ‏ ‏بَعْضِ أَزْوَاجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصُومُ تِسْعَ ذِي الْحِجَّةِ ‏ ‏وَيَوْمَ عَاشُورَاءَ ‏ ‏وَثَلَاثَةَ أَيَّامٍ مِنْ كُلِّ شَهْرٍ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏أَوَّلَ اثْنَيْنِ مِنْ الشَّهْرِ وَخَمِيسَيْنِ ‏","","",""],[21303,21303,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي هَمَّامٍ الشَّعْبَانِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏رَجُلٌ مِنْ خَثْعَمَ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَزْوَةِ ‏ ‏تَبُوكَ ‏ ‏فَوَقَفَ ذَاتَ لَيْلَةٍ وَاجْتَمَعَ عَلَيْهِ أَصْحَابُهُ فَقَالَ ‏ ‏إِنَّ اللَّهَ أَعْطَانِي اللَّيْلَةَ الْكَنْزَيْنِ كَنْزَ ‏ ‏فَارِسَ ‏ ‏وَالرُّومِ ‏ ‏وَأَمَدَّنِي بِالْمُلُوكِ مُلُوكِ ‏ ‏حِمْيَرَ ‏ ‏إِلَّا الْأَحْمَرَيْنِ وَلَا مُلْكَ إِلَّا لِلَّهِ يَأْتُونَ يَأْخُذُونَ مِنْ مَالِ اللَّهِ وَيُقَاتِلُونَ فِي سَبِيلِ اللَّهِ قَالَهَا ثَلَاثًا ‏","","",""],[21304,21304,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏حَدَّثَنَا ‏ ‏حُصَيْنٌ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ قَوْمِهِ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَلَيَّ خَاتَمٌ مِنْ ذَهَبٍ فَأَخَذَ جَرِيدَةً فَضَرَبَ بِهَا كَفِّي وَقَالَ اطْرَحْهُ قَالَ فَخَرَجْتُ فَطَرَحْتُهُ ثُمَّ عُدْتُ إِلَيْهِ فَقَالَ مَا فَعَلَ الْخَاتَمُ قَالَ قُلْتُ طَرَحْتُهُ قَالَ ‏ ‏إِنَّمَا أَمَرْتُكَ أَنْ تَسْتَمْتِعَ بِهِ وَلَا تَطْرَحَهُ ‏","","",""],[21305,21305,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏قَالَ ‏ ‏كُنْتُ جَالِسًا مَعَ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ الْمُزَنِيِّ ‏ ‏فَدَخَلَ ‏ ‏شَابَّانِ ‏ ‏مِنْ وَلَدِ ‏ ‏عُمَرَ ‏ ‏فَصَلَّيَا رَكْعَتَيْنِ بَعْدَ الْعَصْرِ فَأَرْسَلَ إِلَيْهِمَا فَدَعَاهُمَا فَقَالَ مَا هَذِهِ الصَّلَاةُ الَّتِي صَلَّيْتُمَاهَا وَقَدْ كَانَ أَبُوكُمَا يَنْهَى عَنْهَا قَالَا حَدَّثَتْنَا ‏ ‏عَائِشَةُ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهَا ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّاهُمَا عِنْدَهَا فَسَكَتَ وَلَمْ يَرُدَّ عَلَيْهِمَا شَيْئًا ‏","","",""],[21306,21306,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمَلِيحِ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏وَكَانَ لِجَدِّهِ صُحْبَةٌ ‏ ‏أَنَّهُ خَرَجَ زَائِرًا لِرَجُلٍ مِنْ إِخْوَانِهِ فَبَلَغَهُ شَكَاتُهُ قَالَ فَدَخَلَ عَلَيْهِ فَقَالَ أَتَيْتُكَ زَائِرًا عَائِدًا وَمُبَشِّرًا قَالَ كَيْفَ جَمَعْتَ هَذَا كُلَّهُ قَالَ خَرَجْتُ وَأَنَا أُرِيدُ زِيَارَتَكَ فَبَلَغَتْنِي شَكَاتُكَ فَكَانَتْ عِيَادَةً وَأُبَشِّرُكَ بِشَيْءٍ سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا سَبَقَتْ لِلْعَبْدِ مِنْ اللَّهِ مَنْزِلَةٌ لَمْ يَبْلُغْهَا بِعَمَلِهِ ابْتَلَاهُ اللَّهُ فِي جَسَدِهِ أَوْ فِي مَالِهِ أَوْ فِي وَلَدِهِ ثُمَّ صَبَّرَهُ حَتَّى يُبْلِغَهُ الْمَنْزِلَةَ الَّتِي سَبَقَتْ لَهُ مِنْهُ ‏","","",""],[21307,21307,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي عَمْرٍو الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي ‏ ‏أُبْدِعَ ‏ ‏بِي فَاحْمِلْنِي قَالَ فَقَالَ لَيْسَ عِنْدِي قَالَ فَقَالَ رَجُلٌ يَا رَسُولَ اللَّهِ أَفَلَا أَدُلُّهُ عَلَى مَنْ يَحْمِلُهُ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ دَلَّ عَلَى خَيْرٍ فَلَهُ مِثْلُ أَجْرِ فَاعِلِهِ ‏","","",""],[21308,21308,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ رَجَاءٍ ‏ ‏عَنْ ‏ ‏أَوْسِ بْنِ ضَمْعَجٍ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَؤُمُّ الْقَوْمَ أَقْرَؤُهُمْ لِكِتَابِ اللَّهِ فَإِنْ كَانُوا فِي الْقِرَاءَةِ سَوَاءً فَأَعْلَمُهُمْ بِالسُّنَّةِ فَأَقْدَمُهُمْ هِجْرَةً فَإِنْ كَانُوا فِي الْهِجْرَةِ سَوَاءً فَأَكْبَرُهُمْ سِنًّا وَلَا تَؤُمَّنَّ رَجُلًا فِي سُلْطَانِهِ وَلَا تَجْلِسْ عَلَى ‏ ‏تَكْرِمَتِهِ فِي بَيْتِهِ حَتَّى يَأْذَنَ لَكَ ‏","","",""],[21309,21309,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الدَّسْتُوَائِيُّ ‏ ‏وَيَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏الدَّسْتُوَائِيُّ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ اللَّهِ الْجَدَلِيِّ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَمْرٍو أَبِي مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ ‏ ‏يُوتِرُ ‏ ‏مِنْ أَوَّلِ اللَّيْلِ وَأَوْسَطِهِ وَآخِرِهِ ‏","","",""],[21310,21310,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْحَمِيدِ بْنِ جَعْفَرٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏حَكِيمِ بْنِ أَفْلَحَ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِلْمُسْلِمِ عَلَى الْمُسْلِمِ أَرْبَعُ خِلَالٍ أَنْ يُجِيبَهُ إِذَا دَعَاهُ ‏ ‏وَيُشَمِّتَهُ ‏ ‏إِذَا عَطَسَ وَإِذَا مَرِضَ أَنْ ‏ ‏يَعُودَهُ ‏ ‏وَإِذَا مَاتَ أَنْ يَشْهَدَهُ ‏","","",""],[21311,21311,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ ‏ ‏حَدَّثَنَا ‏ ‏قَيْسٌ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏قَالَ ‏ ‏أَشَارَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدِهِ نَحْوَ ‏ ‏الْيَمَنِ ‏ ‏فَقَالَ ‏ ‏الْإِيمَانُ هَاهُنَا الْإِيمَانُ هَاهُنَا وَإِنَّ الْقَسْوَةَ وَغِلَظَ الْقُلُوبِ فِي ‏ ‏الْفَدَّادِينَ ‏ ‏عِنْدَ أُصُولِ أَذْنَابِ الْإِبِلِ حَيْثُ يَطْلُعُ قَرْنَا الشَّيْطَانِ فِي ‏ ‏رَبِيعَةَ ‏ ‏وَمُضَرَ ‏","","",""],[21312,21312,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنِي ‏ ‏قَيْسُ بْنُ أَبِي حَازِمٍ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ عُقْبَةَ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏أَتَى رَجُلٌ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنِّي أَتَأَخَّرُ عَنْ صَلَاةِ ‏ ‏الْغَدَاةِ ‏ ‏مِنْ أَجْلِ فُلَانٍ مِمَّا يُطِيلُ بِنَا فَمَا رَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَشَدَّ غَضَبًا فِي مَوْعِظَةٍ مِنْهُ يَوْمَئِذٍ فَقَالَ يَا أَيُّهَا النَّاسُ ‏ ‏إِنَّ مِنْكُمْ لَمُنَفِّرِينَ فَأَيُّكُمْ مَا صَلَّى بِالنَّاسِ فَلْيَتَجَوَّزْ فَإِنَّ فِيهِمْ الضَّعِيفَ وَالْكَبِيرَ وَذَا الْحَاجَةِ ‏","","",""],[21313,21313,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏رِبْعِيٍّ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ مِمَّا أَدْرَكَ النَّاسُ مِنْ كَلَامِ النُّبُوَّةِ الْأُولَى ‏ ‏إِذَا لَمْ تَسْتَحِ فَاصْنَعْ مَا شِئْتَ ‏","","",""],[21314,21314,"","","‏ ‏زِيَادَات الْقُطَيْعِيِّ ‏ ‏قَالَ ‏ ‏ابْنُ مَالِكٍ ‏ ‏حَدَّثَنَا ‏ ‏الْفَضْلُ بْنُ الْحُبَابِ ‏ ‏حَدَّثَنَا ‏ ‏الْقَعْنَبِيُّ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏رِبْعِيٍّ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ مِمَّا أَدْرَكَ النَّاسُ مِنْ كَلَامِ النُّبُوَّةِ الْأُولَى إِذَا لَمْ تَسْتَحِ فَاصْنَعْ مَا شِئْتَ ‏","","",""],[21315,21315,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أُسَامَةَ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏شَقِيقٍ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ عَمْرٍو أَبِي مَسْعُودٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْمُرُ ‏ ‏بِالصَّدَقَةِ ‏ ‏فَيَنْطَلِقُ أَحَدُنَا فَيُحَامِلُ فَيَجِيءُ ‏ ‏بِالْمُدِّ ‏ ‏وَإِنَّ لِبَعْضِهِمْ الْيَوْمَ مِائَةَ أَلْفٍ ‏ ‏قَالَ ‏ ‏شَقِيقٌ ‏ ‏فَرَأَيْتُ أَنَّهُ يُعَرِّضُ بِنَفْسِهِ ‏","","",""],[21316,21316,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَدِيِّ بْنِ ثَابِتٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَفَقَةُ الرَّجُلِ عَلَى أَهْلِهِ يَحْتَسِبُهَا ‏ ‏صَدَقَةٌ ‏","","",""],[21317,21317,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ ‏ ‏عَنْ ‏ ‏عِيَاضِ بْنِ عِيَاضٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏قَالَ ‏ ‏خَطَبَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خُطْبَةً فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ ثُمَّ قَالَ ‏ ‏إِنَّ فِيكُمْ مُنَافِقِينَ فَمَنْ سَمَّيْتُ فَلْيَقُمْ ثُمَّ قَالَ قُمْ يَا فُلَانُ قُمْ يَا فُلَانُ قُمْ يَا فُلَانُ حَتَّى سَمَّى سِتَّةً وَثَلَاثِينَ رَجُلًا ثُمَّ قَالَ إِنَّ فِيكُمْ ‏ ‏أَوْ مِنْكُمْ ‏ ‏فَاتَّقُوا اللَّهَ قَالَ فَمَرَّ ‏ ‏عُمَرُ ‏ ‏عَلَى رَجُلٍ مِمَّنْ سَمَّى مُقَنَّعٍ قَدْ كَانَ يَعْرِفُهُ قَالَ مَا لَكَ قَالَ فَحَدَّثَهُ بِمَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ بُعْدًا لَكَ سَائِرَ الْيَوْمِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏أُرَاهُ ‏ ‏عِيَاضَ بْنَ عِيَاضٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏قَالَ ‏ ‏خَطَبَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[21318,21318,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏أَنَّهُ كَانَ يَضْرِبُ غُلَامًا لَهُ فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاللَّهِ لَلَّهُ أَقْدَرُ عَلَيْكَ مِنْكَ عَلَيْهِ قَالَ يَا نَبِيَّ اللَّهِ فَإِنِّي أُعْتِقُهُ لِوَجْهِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[21319,21319,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي عَمْرٍو الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏أَتَى رَجُلٌ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلَهُ فَقَالَ مَا عِنْدِي مَا ‏ ‏أُعْطِيكَ وَلَكِنْ ائْتِ فُلَانًا فَأَتَى الرَّجُلَ فَأَعْطَاهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ دَلَّ عَلَى خَيْرٍ فَلَهُ مِثْلُ أَجْرِ فَاعِلِهِ ‏ ‏أَوْ عَامِلِهِ ‏","","",""],[21320,21320,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏وَحَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏أَخْبَرَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏نُعَيْمِ بْنِ عَبْدِ اللَّهِ الْمُجْمِرِ ‏ ‏أَنَّ ‏ ‏مُحَمَّدَ بْنَ عَبْدِ اللَّهِ بْنِ زَيْدٍ الْأَنْصَارِيَّ ‏ ‏فِي حَدِيثِ ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏وَعَبْدُ اللَّهِ بْنُ زَيْدٍ ‏ ‏هُوَ الَّذِي كَانَ أُرِيَ النِّدَاءَ بِالصَّلَاةِ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏أَبِي مَسْعُودٍ الْأَنْصَارِيِّ ‏ ‏أَنَّهُ قَالَ ‏ ‏أَتَانَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي مَجْلِسِ ‏ ‏سَعْدِ بْنِ عُبَادَةَ ‏ ‏فَقَالَ لَهُ ‏ ‏بَشِيرُ بْنُ سَعْدٍ ‏ ‏أَمَرَنَا اللَّهُ أَنْ نُصَلِّيَ عَلَيْكَ يَا رَسُولَ اللَّهِ فَكَيْفَ نُصَلِّي عَلَيْكَ قَالَ فَسَكَتَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى تَمَنَّيْنَا أَنَّهُ لَمْ يَسْأَلْهُ ثُمَّ قَالَ قُولُوا ‏ ‏اللَّهُمَّ صَلِّ عَلَى ‏ ‏مُحَمَّدٍ ‏ ‏وَعَلَى آلِ ‏ ‏مُحَمَّدٍ ‏ ‏كَمَا صَلَّيْتَ عَلَى ‏ ‏إِبْرَاهِيمَ ‏ ‏وَبَارِكْ عَلَى ‏ ‏مُحَمَّدٍ ‏ ‏كَمَا بَارَكْتَ عَلَى آلِ ‏ ‏إِبْرَاهِيمَ ‏ ‏فِي الْعَالَمِينَ إِنَّكَ حَمِيدٌ مَجِيدٌ وَالسَّلَامُ كَمَا قَدْ عَلِمْتُمْ ‏","","",""],[21321,21321,"","","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكُ ابْنُ أَنَسٍ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ الزُّهْرِيِّ ‏ ‏أَنَّ ‏ ‏عُمَرَ بْنَ عَبْدِ الْعَزِيزِ ‏ ‏أَخَّرَ الصَّلَاةَ يَوْمًا فَدَخَلَ عَلَيْهِ ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏فَأَخْبَرَهُ أَنَّ ‏ ‏الْمُغِيرَةَ بْنَ شُعْبَةَ ‏ ‏أَخَّرَ الصَّلَاةَ يَوْمًا وَهُوَ ‏ ‏بِالْكُوفَةِ ‏ ‏فَدَخَلَ عَلَيْهِ ‏ ‏أَبُو مَسْعُودٍ الْأَنْصَارِيُّ ‏ ‏فَقَالَ مَا هَذَا يَا ‏ ‏مُغِيرَةُ ‏ ‏أَلَيْسَ قَدْ عَلِمْتَ أَنَّ ‏ ‏جِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏نَزَلَ فَصَلَّى فَصَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ صَلَّى فَصَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ بِهَذَا أُمِرْتُ فَقَالَ ‏ ‏عُمَرُ ‏ ‏لِعُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏اعْلَمْ مَا تُحَدِّثُ بِهِ يَا ‏ ‏عُرْوَةُ ‏ ‏أَوَأَنَّ ‏ ‏جِبْرِيلَ ‏ ‏هُوَ الَّذِي أَقَامَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقْتَ الصَّلَاةِ ‏ ‏فَقَالَ ‏ ‏عُرْوَةُ ‏ ‏كَذَلِكَ كَانَ ‏ ‏بَشِيرُ بْنُ أَبِي مَسْعُودٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏","","",""],[21322,21322,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏قَالَ ‏ ‏بَيْنَا أَنَا أَضْرِبُ مَمْلُوكًا لِي إِذَا رَجُلٌ يُنَادِي مِنْ خَلْفِي اعْلَمْ يَا ‏ ‏أَبَا مَسْعُودٍ ‏ ‏اعْلَمْ يَا ‏ ‏أَبَا مَسْعُودٍ ‏ ‏فَالْتَفَتُّ فَإِذَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ وَاللَّهِ ‏ ‏لَلَّهُ أَقْدَرُ عَلَيْكَ مِنْكَ عَلَى هَذَا قَالَ فَحَلَفْتُ لَا أَضْرِبُ مَمْلُوكًا لِي أَبَدًا ‏","","",""],[21323,21323,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ هِشَامٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِقُرَيْشٍ ‏ ‏إِنَّ هَذَا الْأَمْرَ لَا يَزَالُ فِيكُمْ وَأَنْتُمْ وُلَاتُهُ حَتَّى تُحْدِثُوا أَعْمَالًا فَإِذَا فَعَلْتُمْ ذَلِكَ سَلَّطَ اللَّهُ عَلَيْكُمْ شِرَارَ خَلْقِهِ ‏ ‏فَالْتَحَوْكُمْ ‏ ‏كَمَا ‏ ‏يُلْتَحَى ‏ ‏الْقَضِيبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏قَالَ ‏ ‏فَالْتَحَوْكُمْ ‏ ‏وَكَذَلِكَ ‏ ‏قَالَ ‏ ‏أَبُو أَحْمَدَ ‏ ‏وَقَالَ ‏ ‏فَالْتَحَوْكُمْ ‏ ‏قَالَ ‏ ‏أَبُو نُعَيْمٍ ‏ ‏كَمَا ‏ ‏يُلْتَحَى الْقَضِيبُ ‏","","",""],[21324,21324,"","","‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي عَمْرٍو الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏أَنَّ ‏ ‏رَجُلًا تَصَدَّقَ بِنَاقَةٍ ‏ ‏مَخْطُومَةٍ ‏ ‏فِي سَبِيلِ اللَّهِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيَأْتِيَنَّ ‏ ‏أَوْ لَتَأْتِيَنَّ ‏ ‏بِسَبْعِ مِائَةِ نَاقَةٍ ‏ ‏مَخْطُومَةٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا عَمْرٍو الشَّيْبَانِيَّ ‏ ‏فَذَكَرَهُ وَلَمْ يَشُكَّ قَالَ لَتَأْتِيَنَّ ‏","","",""],[21325,21325,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَمَّادٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏حَدَّثَنَا ‏ ‏سَالِمٌ الْبَرَّادُ ‏ ‏قَالَ ‏ ‏دَخَلْنَا عَلَى ‏ ‏أَبِي مَسْعُودٍ الْأَنْصَارِيِّ ‏ ‏فَسَأَلْنَاهُ عَنْ الصَّلَاةِ فَقَالَ أَلَا أُصَلِّي بِكُمْ كَمَا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي قَالَ فَقَامَ ‏ ‏فَكَبَّرَ وَرَفَعَ يَدَيْهِ ثُمَّ رَكَعَ فَوَضَعَ كَفَّيْهِ عَلَى رُكْبَتَيْهِ ‏ ‏وَجَافَى ‏ ‏بَيْنَ إِبْطَيْهِ قَالَ ثُمَّ قَامَ حَتَّى اسْتَقَرَّ كُلُّ شَيْءٍ مِنْهُ ثُمَّ سَجَدَ فَوَضَعَ كَفَّيْهِ ‏ ‏وَجَافَى ‏ ‏بَيْنَ إِبِطَيْهِ قَالَ ثُمَّ قَامَ حَتَّى اسْتَقَرَّ كُلُّ شَيْءٍ مِنْهُ ثُمَّ صَلَّى أَرْبَعَ رَكَعَاتٍ هَكَذَا ‏","","",""],[21326,21326,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي عَمْرٍو الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏رَفَعَهُ ‏ ‏وَقَالَ ‏ ‏شَاذَانُ ‏ ‏مَرَّةً عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمُسْتَشَارُ مُؤْتَمَنٌ ‏ ‏وَذَكَرَ ‏ ‏شَاذَانُ ‏ ‏أَيْضًا حَدِيثَ ‏ ‏الدَّالِّ عَلَى الْخَيْرِ كَفَاعِلِهِ ‏","","",""],[21327,21327,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُتْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِقُرَيْشٍ ‏ ‏إِنَّ هَذَا الْأَمْرَ لَا يَزَالُ فِيكُمْ وَأَنْتُمْ وُلَاتُهُ مَا لَمْ تُحْدِثُوا فَإِذَا ‏ ‏فَعَلْتُمْ ذَلِكَ سَلَّطَ اللَّهُ عَلَيْكُمْ شِرَارَ خَلْقِهِ ‏ ‏وَالْتَحَوْكُمْ ‏ ‏كَمَا ‏ ‏يُلْتَحَى ‏ ‏الْقَضِيبُ ‏","","",""],[21328,21328,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو قَبِيلٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ الْمُقْرِئَ ‏ ‏يَقُولُ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏أَبِي قَبِيلٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ الْجُبْلَانِيُّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا أُحِبُّ أَنَّ لِي الدُّنْيَا وَمَا فِيهَا بِهَذِهِ الْآيَةِ ‏ { ‏يَا ‏ ‏عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ لَا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعًا إِنَّهُ هُوَ الْغَفُورُ الرَّحِيمُ ‏} ‏فَقَالَ رَجُلٌ يَا رَسُولَ اللَّهِ فَمَنْ أَشْرَكَ فَسَكَتَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ قَالَ إِلَّا مَنْ أَشْرَكَ ثَلَاثَ مَرَّاتِ ‏","","",""],[21329,21329,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جُحَادَةَ ‏ ‏حَدَّثَنِي ‏ ‏حُمَيْدٌ الشَّامِيُّ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ الْمَنْبِهِيِّ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سَافَرَ آخِرُ عَهْدِهِ بِإِنْسَانٍ ‏ ‏فَاطِمَةُ ‏ ‏وَأَوَّلُ مَنْ يَدْخُلُ عَلَيْهِ إِذَا قَدِمَ ‏ ‏فَاطِمَةُ ‏ ‏قَالَ فَقَدِمَ مِنْ غَزَاةٍ لَهُ فَأَتَاهَا فَإِذَا هُوَ يَمْسَحُ عَلَى بَابِهَا وَرَأَى عَلَى ‏ ‏الْحَسَنِ ‏ ‏وَالْحُسَيْنِ ‏ ‏قَلْبَيْنِ مِنْ فِضَّةٍ فَرَجَعَ وَلَمْ يَدْخُلْ عَلَيْهَا فَلَمَّا رَأَتْ ذَلِكَ ‏ ‏فَاطِمَةُ ‏ ‏ظَنَّتْ أَنَّهُ لَمْ يَدْخُلْ عَلَيْهَا مِنْ أَجْلِ مَا رَأَى فَهَتَكَتْ السِّتْرَ وَنَزَعَتْ الْقَلْبَيْنِ مِنْ الصَّبِيَّيْنِ فَقَطَعَتْهُمَا فَبَكَى الصَّبِيَّانِ فَقَسَمَتْهُ بَيْنَهُمَا فَانْطَلَقَا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُمَا يَبْكِيَانِ فَأَخَذَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْهُمَا فَقَالَ يَا ‏ ‏ثَوْبَانُ ‏ ‏اذْهَبْ بِهَذَا إِلَى بَنِي فُلَانٍ أَهْلُ بَيْتٍ ‏ ‏بِالْمَدِينَةِ ‏ ‏وَاشْتَرِ ‏ ‏لِفَاطِمَةَ ‏ ‏قِلَادَةً مِنْ ‏ ‏عَصَبٍ ‏ ‏وَسِوَارَيْنِ مِنْ عَاجٍ فَإِنَّ هَؤُلَاءِ أَهْلُ بَيْتِي وَلَا أُحِبُّ أَنْ يَأْكُلُوا طَيِّبَاتِهِمْ فِي حَيَاتِهِمْ الدُّنْيَا ‏","","",""],[21330,21330,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏وَأَبُو الْيَمَانِ ‏ ‏وَهَذَا حَدِيثُ ‏ ‏إِسْحَاقَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏رَاشِدِ بْنِ دَاوُدَ الْأُمْلُوكِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ الرَّحَبِيِّ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي مَسِيرٍ لَهُ ‏ ‏إِنَّا ‏ ‏مُدْلِجُونَ ‏ ‏فَلَا ‏ ‏يُدْلِجَنَّ ‏ ‏مُصْعِبٌ وَلَا مُضْعِفٌ ‏ ‏فَأَدْلَجَ ‏ ‏رَجُلٌ عَلَى نَاقَةٍ لَهُ صَعْبَةٍ فَسَقَطَ ‏ ‏فَانْدَقَّتْ ‏ ‏فَخِذُهُ فَمَاتَ فَأَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالصَّلَاةِ عَلَيْهِ ثُمَّ أَمَرَ مُنَادِيًا يُنَادِي فِي النَّاسِ إِنَّ الْجَنَّةَ لَا تَحِلُّ لِعَاصٍ إِنَّ الْجَنَّةَ لَا تَحِلُّ لِعَاصٍ ثَلَاثَ مَرَّاتٍ ‏","","",""],[21331,21331,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏أَبِي عَمَّارٍ شَدَّادٍ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ الرَّحَبِيِّ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَرَادَ أَنْ يَنْصَرِفَ مِنْ صَلَاتِهِ اسْتَغْفَرَ ثَلَاثَ مَرَّاتٍ ثُمَّ قَالَ ‏ ‏اللَّهُمَّ أَنْتَ السَّلَامُ وَمِنْكَ السَّلَامُ تَبَارَكْتَ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ ‏","","",""],[21332,21332,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي الْعَالِيَةِ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ يَتَكَفَّلُ لِي بِوَاحِدَةٍ وَأَتَكَفَّلُ لَهُ بِالْجَنَّةِ قَالَ ‏ ‏ثَوْبَانُ ‏ ‏أَنَا قَالَ لَا تَسْأَلْ النَّاسَ ‏ ‏يَعْنِي شَيْئًا ‏ ‏قَالَ نَعَمْ ‏ ‏قَالَ ‏ ‏فَكَانَ لَا يَسْأَلُ ‏","","",""],[21333,21333,"","","‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ المُهَاجِرِ ‏ ‏عَنِ ‏ ‏الْعَبَّاسِ بْنِ سَالِمٍ اللَّخْمِيِّ ‏ ‏قَالَ ‏ ‏بَعَثَ ‏ ‏عُمَرُ بْنُ عَبْدِ الْعَزِيزِ ‏ ‏إِلَى ‏ ‏أَبِي سَلَّامٍ الْحَبَشِيِّ ‏ ‏فَحُمِلَ إِلَيْهِ عَلَى الْبَرِيدِ يَسْأَلُهُ عَنْ الْحَوْضِ فَقُدِمَ بِهِ عَلَيْهِ فَسَأَلَهُ فَقَالَ سَمِعْتُ ‏ ‏ثَوْبَانَ ‏ ‏يَقُولُ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ حَوْضِي مِنْ ‏ ‏عَدَنَ ‏ ‏إِلَى ‏ ‏عَمَّانَ الْبَلْقَاءِ ‏ ‏مَاؤُهُ أَشَدُّ بَيَاضًا مِنْ اللَّبَنِ وَأَحْلَى مِنْ الْعَسَلِ ‏ ‏وَأَكَاوِيبُهُ عَدَدُ النُّجُومِ مَنْ شَرِبَ مِنْهُ شَرْبَةً لَمْ يَظْمَأْ بَعْدَهَا أَبَدًا أَوَّلُ النَّاسِ وُرُودًا عَلَيْهِ فُقَرَاءُ ‏ ‏الْمُهَاجِرِينَ ‏ ‏فَقَالَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏مَنْ هُمْ ‏ ‏يَا رَسُولَ اللَّهِ قَالَ هُمْ ‏ ‏الشُّعْثُ ‏ ‏رُءُوسًا ‏ ‏الدُّنْسُ ‏ ‏ثِيَابًا الَّذِينَ لَا يَنْكِحُونَ ‏ ‏الْمُتَنَعِّمَاتِ ‏ ‏وَلَا تُفْتَحُ لَهُمْ أَبْوَابُ ‏ ‏السُّدَدِ ‏ ‏فَقَالَ ‏ ‏عُمَرُ بْنُ عَبْدِ الْعَزِيزِ ‏ ‏لَقَدْ نَكَحْتُ ‏ ‏الْمُتَنَعِّمَاتِ ‏ ‏وَفُتِحَتْ لِي ‏ ‏السُّدَدُ ‏ ‏إِلَّا أَنْ يَرْحَمَنِي اللَّهُ وَاللَّهِ لَا جَرَمَ أَنْ لَا أَدْهُنَ رَأْسِي حَتَّى ‏ ‏يَشْعَثَ ‏ ‏وَلَا أَغْسِلَ ثَوْبِي الَّذِي يَلِي جَسَدِي حَتَّى يَتَّسِخَ ‏","","",""],[21334,21334,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏مِنْ كِتَابِهِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏حَدَّثَنَا ‏ ‏شَيْخٌ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ قَتَلَ صَغِيرًا أَوْ كَبِيرًا أَوْ أَحْرَقَ نَخْلًا أَوْ قَطَعَ شَجَرَةً مُثْمِرَةً أَوْ ذَبَحَ شَاةً لِإِهَابِهَا لَمْ يَرْجِعْ ‏ ‏كَفَافًا ‏","","",""],[21335,21335,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏وَأَبَانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏مَعْدَانَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ فَارَقَ الرُّوحُ الْجَسَدَ وَهُوَ بَرِيءٌ مِنْ ثَلَاثٍ دَخَلَ الْجَنَّةَ الْكِبْرِ وَالدَّيْنِ وَالْغُلُولِ ‏","","",""],[21336,21336,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏قَالَ ‏ ‏قِيلَ ‏ ‏لِثَوْبَانَ ‏ ‏حَدِّثْنَا عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ تَكْذِبُونَ عَلَيَّ وَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا مِنْ مُسْلِمٍ يَسْجُدُ لِلَّهِ سَجْدَةً إِلَّا رَفَعَهُ اللَّهُ بِهَا دَرَجَةً أَوْ حَطَّ عَنْهُ بِهَا خَطِيئَةً ‏","","",""],[21337,21337,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ غَنْمٍ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَفْطَرَ ‏ ‏الْحَاجِمُ ‏ ‏وَالْمَحْجُومُ ‏","","",""],[21338,21338,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي الْجُودِيِّ ‏ ‏عَنْ ‏ ‏بَلْجٍ ‏ ‏عَنْ ‏ ‏أَبِي شَيْبَةَ الْمَهْرِيِّ ‏ ‏قَالَ ‏ ‏وَكَانَ قَاصَّ النَّاسِ ‏ ‏بِقُسْطَنْطِينِيَّةَ ‏ ‏قَالَ ‏ ‏قِيلَ ‏ ‏لِثَوْبَانَ ‏ ‏حَدِّثْنَا عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَاءَ فَأَفْطَرَ ‏","","",""],[21339,21339,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا ‏ ‏عَادَ ‏ ‏الرَّجُلُ الْمُسْلِمُ أَخَاهُ الْمُسْلِمَ فَهُوَ فِي ‏ ‏مَخْرَفَةِ ‏ ‏الْجَنَّةِ ‏","","",""],[21340,21340,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِأَبِي الْعَالِيَةِ ‏ ‏مَا ‏ ‏ثَوْبَانُ ‏ ‏قَالَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ تَكَفَّلَ لِي أَنْ لَا يَسْأَلَ شَيْئًا وَأَتَكَفَّلُ لَهُ بِالْجَنَّةِ فَقَالَ ‏ ‏ثَوْبَانُ ‏ ‏أَنَا ‏ ‏فَكَانَ لَا يَسْأَلُ أَحَدًا شَيْئًا ‏","","",""],[21341,21341,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ الرَّحَبِيِّ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِذَا ‏ ‏عَادَ ‏ ‏الرَّجُلُ أَخَاهُ فَإِنَّهُ فِي ‏ ‏أَخْرَافِ ‏ ‏الْجَنَّةِ حَتَّى يَرْجِعَ ‏","","",""],[21342,21342,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو قَطَنٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏مَعْدَانَ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ تَبِعَ جَنَازَةً فَلَهُ قِيرَاطٌ وَمَنْ شَهِدَ دَفْنَهَا فَلَهُ قِيرَاطَانِ قِيلَ وَمَا الْقِيرَاطَانِ قَالَ أَصْغَرُهُمَا مِثْلُ ‏ ‏أُحُدٍ ‏","","",""],[21343,21343,"","","‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْأَوْزَاعِيَّ ‏ ‏يَقُولُ حَدَّثَنِي ‏ ‏الْوَلِيدُ بْنُ هِشَامٍ الْمُعَيْطِيُّ ‏ ‏حَدَّثَنِي ‏ ‏مَعْدَانُ بْنُ أَبِي طَلْحَةَ الْيَعْمُرِيُّ ‏ ‏قَالَ ‏ ‏لَقِيتُ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ أَخْبِرْنِي بِعَمَلٍ أَعْمَلُهُ يُدْخِلُنِي اللَّهُ بِهِ الْجَنَّةَ ‏ ‏أَوْ قَالَ قُلْتُ بِأَحَبِّ الْأَعْمَالِ إِلَى اللَّهِ ‏ ‏فَسَكَتَ ثُمَّ سَأَلْتُهُ الثَّالِثَةَ فَقَالَ سَأَلْتُ عَنْ ذَلِكَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏عَلَيْكَ بِكَثْرَةِ السُّجُودِ فَإِنَّكَ لَا تَسْجُدُ لِلَّهِ سَجْدَةً إِلَّا رَفَعَكَ اللَّهُ بِهَا دَرَجَةً وَحَطَّ عَنْكَ بِهَا خَطِيئَةً قَالَ ‏ ‏مَعْدَانُ ‏ ‏ثُمَّ لَقِيتُ ‏ ‏أَبَا الدَّرْدَاءِ ‏ ‏فَسَأَلْتُهُ فَقَالَ لِي مِثْلَ مَا قَالَ لِي ‏ ‏ثَوْبَانُ ‏","","",""],[21344,21344,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَقِيمُوا وَلَنْ تُحْصُوا وَاعْلَمُوا أَنَّ خَيْرَ أَعْمَالِكُمْ الصَّلَاةُ وَلَنْ يُحَافِظَ عَلَى الْوُضُوءِ إِلَّا مُؤْمِنٌ ‏","","",""],[21345,21345,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَمَّنْ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّمَا امْرَأَةٍ سَأَلَتْ زَوْجَهَا الطَّلَاقَ مِنْ غَيْرِ مَا بَأْسٍ فَحَرَامٌ عَلَيْهَا رَائِحَةُ الْجَنَّةِ ‏","","",""],[21346,21346,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَمَّنْ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَفْضَلَ دِينَارٍ دِينَارٌ أَنْفَقَهُ رَجُلٌ عَلَى عِيَالِهِ أَوْ عَلَى دَابَّتِهِ فِي سَبِيلِ اللَّهِ أَوْ عَلَى أَصْحَابِهِ فِي سَبِيلِ اللَّهِ ‏","","",""],[21347,21347,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏يَعِيشَ بْنِ الْوَلِيدِ بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏مَعْدَانَ ‏ ‏عَنْ ‏ ‏أَبِي الدَّرْدَاءِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَاءَ فَأَفْطَرَ قَالَ فَلَقِيتُ ‏ ‏ثَوْبَانَ ‏ ‏فِي مَسْجِدِ ‏ ‏دِمَشْقَ ‏ ‏فَسَأَلْتُهُ عَنْ ذَلِكَ فَقَالَ أَنَا صَبَبْتُ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَضُوءَهُ ‏","","",""],[21348,21348,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ الدَّسْتُوَائِيُّ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَى عَلَى رَجُلٍ ‏ ‏يَحْتَجِمُ ‏ ‏فِي رَمَضَانَ فَقَالَ ‏ ‏أَفْطَرَ ‏ ‏الْحَاجِمُ ‏ ‏وَالْمَحْجُومُ ‏","","",""],[21349,21349,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏ثَوْرٍ ‏ ‏عَنْ ‏ ‏رَاشِدِ بْنِ سَعْدٍ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏بَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَرِيَّةً ‏ ‏فَأَصَابَهُمْ الْبَرْدُ فَلَمَّا قَدِمُوا عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَكَوْا إِلَيْهِ مَا أَصَابَهُمْ مِنْ الْبَرْدِ ‏ ‏فَأَمَرَهُمْ أَنْ يَمْسَحُوا عَلَى ‏ ‏الْعَصَائِبِ ‏ ‏وَالتَّسَاخِينِ ‏","","",""],[21350,21350,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏مَعْدَانَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ صَلَّى عَلَى جِنَازَةٍ فَلَهُ قِيرَاطٌ فَإِنْ شَهِدَ دَفْنَهَا فَلَهُ قِيرَاطَانِ الْقِيرَاطُ مِثْلُ ‏ ‏أُحُدٍ ‏","","",""],[21351,21351,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ يَتَقَبَّلُ لِي بِوَاحِدَةٍ وَأَتَقَبَّلُ لَهُ بِالْجَنَّةِ قَالَ قُلْتُ أَنَا قَالَ لَا تَسْأَلْ النَّاسَ شَيْئًا ‏ ‏فَكَانَ ‏ ‏ثَوْبَانُ ‏ ‏يَقَعُ سَوْطُهُ وَهُوَ رَاكِبٌ فَلَا يَقُولُ لِأَحَدٍ نَاوِلْنِيهِ حَتَّى يَنْزِلَ فَيَتَنَاوَلَهُ ‏","","",""],[21352,21352,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عِيسَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الرَّجُلَ لَيُحْرَمُ الرِّزْقَ بِالذَّنْبِ يُصِيبُهُ وَلَا يَرُدُّ الْقَدَرَ إِلَّا الدُّعَاءُ وَلَا يَزِيدُ فِي الْعُمُرِ إِلَّا الْبِرُّ ‏","","",""],[21353,21353,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا رَأَيْتُمْ الرَّايَاتِ السُّودَ قَدْ جَاءَتْ مِنْ ‏ ‏خُرَاسَانَ ‏ ‏فَأْتُوهَا فَإِنَّ فِيهَا خَلِيفَةَ اللَّهِ ‏ ‏الْمَهْدِيَّ ‏","","",""],[21354,21354,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَقِيمُوا ‏ ‏لِقُرَيْشٍ ‏ ‏مَا اسْتَقَامُوا لَكُمْ ‏","","",""],[21355,21355,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي الْأَشْعَثِ الصَّنْعَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ الرَّحَبِيِّ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ ‏ ‏عَادَ ‏ ‏مَرِيضًا لَمْ يَزَلْ فِي ‏ ‏خُرْفَةِ ‏ ‏الْجَنَّةِ قِيلَ وَمَا ‏ ‏خُرْفَةُ ‏ ‏الْجَنَّةِ قَالَ ‏ ‏جَنَاهَا ‏","","",""],[21356,21356,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏عَنْ ‏ ‏هَمَّامٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏مَعْدَانَ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ فَارَقَ الرُّوحُ الْجَسَدَ وَهُوَ بَرِيءٌ مِنْ ثَلَاثٍ الْكِبْرِ وَالْغُلُولِ وَالدَّيْنِ فَهُوَ فِي الْجَنَّةِ ‏ ‏أَوْ وَجَبَتْ لَهُ الْجَنَّةُ ‏","","",""],[21357,21357,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ يَعْنِي ابْنَ صَالِحٍ ‏ ‏عَنْ ‏ ‏أَبِي الزَّاهِرِيَّةِ ‏ ‏عَنْ ‏ ‏جُبَيْرٍ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏ذَبَحَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُضْحِيَّةً ثُمَّ قَالَ يَا ‏ ‏ثَوْبَانُ ‏ ‏أَصْلِحْ لَحْمَ هَذِهِ الشَّاةِ قَالَ فَمَا زِلْتُ أُطْعِمُهُ مِنْهَا ‏ ‏حَتَّى قَدِمَ ‏ ‏الْمَدِينَةَ ‏","","",""],[21358,21358,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏إِسْرَائِيلَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏لَمَّا أُنْزِلَتْ ‏ { ‏الَّذِينَ يَكْنِزُونَ الذَّهَبَ وَالْفِضَّةَ وَلَا يُنْفِقُونَهَا فِي سَبِيلِ اللَّهِ ‏} ‏قَالَ كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَعْضِ أَسْفَارِهِ فَقَالَ بَعْضُ أَصْحَابِهِ قَدْ نَزَلَ فِي الذَّهَبِ وَالْفِضَّةِ مَا نَزَلَ فَلَوْ أَنَّا عَلِمْنَا أَيُّ الْمَالِ خَيْرٌ اتَّخَذْنَاهُ فَقَالَ ‏ ‏أَفْضَلُهُ لِسَانًا ذَاكِرًا وَقَلْبًا شَاكِرًا وَزَوْجَةً مُؤْمِنَةً تُعِينُهُ عَلَى إِيمَانِهِ ‏","","",""],[21359,21359,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا أَخَافُ عَلَى أُمَّتِي الْأَئِمَّةَ الْمُضِلِّينَ ‏","","",""],[21360,21360,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا أَخَافُ عَلَى أُمَّتِي الْأَئِمَّةَ الْمُضِلِّينَ ‏","","",""],[21361,21361,"","","‏ ‏وَبِهِ قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ ‏ ‏زَوَى ‏ ‏لِي الْأَرْضَ ‏ ‏أَوْ قَالَ إِنَّ رَبِّي ‏ ‏زَوَى ‏ ‏لِي الْأَرْضَ ‏ ‏فَرَأَيْتُ مَشَارِقَهَا وَمَغَارِبَهَا وَإِنَّ مُلْكَ أُمَّتِي سَيَبْلُغُ مَا ‏ ‏زُوِيَ ‏ ‏لِي مِنْهَا وَإِنِّي أُعْطِيتُ الْكَنْزَيْنِ الْأَحْمَرَ وَالْأَبْيَضَ وَإِنِّي سَأَلْتُ رَبِّي لِأُمَّتِي أَنْ لَا يَهْلِكُوا بِسَنَةٍ بِعَامَّةٍ وَلَا يُسَلِّطَ عَلَيْهِمْ عَدُوًّا مِنْ سِوَى أَنْفُسِهِمْ يَسْتَبِيحُ ‏ ‏بَيْضَتَهُمْ ‏ ‏وَإِنَّ رَبِّي عَزَّ وَجَلَّ قَالَ ‏ ‏يَا ‏ ‏مُحَمَّدُ ‏ ‏إِنِّي إِذَا قَضَيْتُ قَضَاءً فَإِنَّهُ لَا يُرَدُّ ‏ ‏وَقَالَ ‏ ‏يُونُسُ ‏ ‏لَا يُرَدُّ ‏ ‏وَإِنِّي أَعْطَيْتُكَ لِأُمَّتِكَ أَنْ لَا أُهْلِكَهُمْ بِسَنَةٍ بِعَامَّةٍ وَلَا أُسَلِّطَ عَلَيْهِمْ عَدُوًّا مِنْ سِوَى أَنْفُسِهِمْ يَسْتَبِيحُ ‏ ‏بَيْضَتَهُمْ ‏ ‏وَلَوْ اجْتَمَعَ عَلَيْهِمْ مَنْ بَيْنَ أَقْطَارِهَا ‏ ‏أَوْ قَالَ مَنْ بِأَقْطَارِهَا ‏ ‏حَتَّى يَكُونَ بَعْضُهُمْ ‏ ‏يَسْبِي بَعْضًا وَإِنَّمَا أَخَافُ عَلَى أُمَّتِي الْأَئِمَّةَ الْمُضِلِّينَ وَإِذَا وُضِعَ فِي أُمَّتِي السَّيْفُ لَمْ يُرْفَعْ عَنْهُمْ إِلَى يَوْمِ الْقِيَامَةِ وَلَا تَقُومُ السَّاعَةُ حَتَّى يَلْحَقَ قَبَائِلُ مِنْ أُمَّتِي بِالْمُشْرِكِينَ حَتَّى تَعْبُدَ قَبَائِلُ مِنْ أُمَّتِي الْأَوْثَانَ وَإِنَّهُ سَيَكُونُ فِي أُمَّتِي كَذَّابُونَ ثَلَاثُونَ كُلُّهُمْ يَزْعُمُ أَنَّهُ نَبِيٌّ وَأَنَا خَاتَمُ النَّبِيِّينَ لَا نَبِيَّ بَعْدِي وَلَا تَزَالُ طَائِفَةٌ مِنْ أُمَّتِي عَلَى الْحَقِّ ظَاهِرِينَ لَا يَضُرُّهُمْ مَنْ خَالَفَهُمْ حَتَّى يَأْتِيَ أَمْرُ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[21362,21362,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏بَقِيَّةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ سَالِمٍ ‏ ‏وَأَبُو بَكْرِ بْنُ الْوَلِيدِ الزُّبَيْدِيُّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْوَلِيدِ الزُّبَيْدِيِّ ‏ ‏عَنْ ‏ ‏لُقْمَانَ بْنِ عَامِرٍ الْوُصَابِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الْأَعْلَى بْنِ عَدِيٍّ الْبَهْرَانِيِّ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عِصَابَتَانِ مِنْ أُمَّتِي أَحْرَزَهُمْ اللَّهُ مِنْ النَّارِ عِصَابَةٌ ‏ ‏تَغْزُو ‏ ‏الْهِنْدَ ‏ ‏وَعِصَابَةٌ تَكُونُ مَعَ ‏ ‏عِيسَى ابْنِ مَرْيَمَ ‏ ‏عَلَيْهِ السَّلَام ‏","","",""],[21363,21363,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏حَدَّثَنَا ‏ ‏الْمُبَارَكُ بْنُ فَضَالَةَ ‏ ‏حَدَّثَنَا ‏ ‏مَرْزُوقٌ أَبُو عَبْدِ اللَّهِ الْحِمْصِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَسْمَاءَ الرَّحَبِيُّ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُوشِكُ أَنْ تَدَاعَى عَلَيْكُمْ الْأُمَمُ مِنْ كُلِّ أُفُقٍ كَمَا تَدَاعَى الْأَكَلَةُ عَلَى ‏ ‏قَصْعَتِهَا ‏ ‏قَالَ قُلْنَا يَا رَسُولَ اللَّهِ أَمِنْ قِلَّةٍ بِنَا يَوْمَئِذٍ قَالَ أَنْتُمْ يَوْمَئِذٍ كَثِيرٌ وَلَكِنْ تَكُونُونَ ‏ ‏غُثَاءً ‏ ‏كَغُثَاءِ ‏ ‏السَّيْلِ يَنْتَزِعُ ‏ ‏الْمَهَابَةَ ‏ ‏مِنْ قُلُوبِ عَدُوِّكُمْ وَيَجْعَلُ فِي قُلُوبِكُمْ الْوَهْنَ قَالَ قُلْنَا وَمَا الْوَهْنُ قَالَ حُبُّ الْحَيَاةِ وَكَرَاهِيَةُ الْمَوْتِ ‏","","",""],[21364,21364,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنِي ‏ ‏زَيْدُ بْنُ سَلَّامٍ ‏ ‏أَنَّ ‏ ‏جَدَّهُ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏أَبَا أَسْمَاءَ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَهُ ‏ ‏أَنَّ ‏ ‏ابْنَةَ هُبَيْرَةَ ‏ ‏دَخَلَتْ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَفِي يَدِهَا خَوَاتِيمُ مِنْ ذَهَبٍ يُقَالُ لَهَا ‏ ‏الْفَتَخُ ‏ ‏فَجَعَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَعُ يَدَهَا بِعُصَيَّةٍ مَعَهُ يَقُولُ لَهَا يَسُرُّكِ أَنْ يَجْعَلَ اللَّهُ فِي يَدِكِ خَوَاتِيمَ مِنْ نَارٍ فَأَتَتْ ‏ ‏فَاطِمَةَ ‏ ‏فَشَكَتْ إِلَيْهَا مَا صَنَعَ بِهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ وَانْطَلَقْتُ أَنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَامَ خَلْفَ الْبَابِ وَكَانَ إِذَا اسْتَأْذَنَ قَامَ خَلْفَ الْبَابِ ‏ ‏قَالَ فَقَالَتْ لَهَا ‏ ‏فَاطِمَةُ ‏ ‏انْظُرِي إِلَى هَذِهِ السِّلْسِلَةِ الَّتِي أَهْدَاهَا إِلَيَّ ‏ ‏أَبُو حَسَنٍ ‏ ‏قَالَ وَفِي يَدِهَا سِلْسِلَةٌ مِنْ ذَهَبٍ فَدَخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا ‏ ‏فَاطِمَةُ ‏ ‏بِالْعَدْلِ أَنْ يَقُولَ النَّاسُ ‏ ‏فَاطِمَةُ بِنْتُ مُحَمَّدٍ ‏ ‏وَفِي يَدِكِ سِلْسِلَةٌ مِنْ نَارٍ ثُمَّ ‏ ‏عَذَمَهَا ‏ ‏عَذْمًا ‏ ‏شَدِيدًا ثُمَّ خَرَجَ وَلَمْ يَقْعُدْ فَأَمَرَتْ بِالسِّلْسِلَةِ فَبِيعَتْ فَاشْتَرَتْ بِثَمَنِهَا عَبْدًا فَأَعْتَقَتْهُ فَلَمَّا سَمِعَ بِذَلِكَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَبَّرَ وَقَالَ الْحَمْدُ لِلَّهِ الَّذِي نَجَّى ‏ ‏فَاطِمَةَ ‏ ‏مِنْ النَّارِ ‏","","",""],[21365,21365,"","","‏ ‏حَدَّثَنَا ‏ ‏الْأَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ يَعْنِي ابْنَ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏أَبِي الْخَطَّابِ ‏ ‏عَنْ ‏ ‏أَبِي زُرْعَةَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏لَعَنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الرَّاشِيَ وَالْمُرْتَشِيَ ‏ ‏وَالرَّائِشَ ‏ ‏يَعْنِي الَّذِي يَمْشِي بَيْنَهُمَا ‏","","",""],[21366,21366,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏مَيْمُونٌ أَبُو مُحَمَّدٍ الْمُزَنِيُّ التَّمِيمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبَّادٍ الْمَخْزُومِيُّ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ سَرَّهُ النَّسَاءُ فِي الْأَجَلِ وَالزِّيَادَةُ فِي الرِّزْقِ فَلْيَصِلْ رَحِمَهُ ‏","","",""],[21367,21367,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏مَيْمُونٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبَّادٍ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِنَّ الْعَبْدَ لَيَلْتَمِسُ ‏ ‏مَرْضَاةَ ‏ ‏اللَّهِ وَلَا يَزَالُ بِذَلِكَ فَيَقُولُ اللَّهُ عَزَّ وَجَلَّ ‏ ‏لِجِبْرِيلَ ‏ ‏إِنَّ فُلَانًا عَبْدِي يَلْتَمِسُ أَنْ يُرْضِيَنِي أَلَا وَإِنَّ رَحْمَتِي عَلَيْهِ فَيَقُولُ ‏ ‏جِبْرِيلُ ‏ ‏رَحْمَةُ اللَّهِ عَلَى فُلَانٍ وَيَقُولُهَا حَمَلَةُ الْعَرْشِ وَيَقُولُهَا مَنْ حَوْلَهُمْ حَتَّى يَقُولَهَا أَهْلُ السَّمَوَاتِ السَّبْعِ ثُمَّ تَهْبِطُ لَهُ إِلَى الْأَرْضِ ‏","","",""],[21368,21368,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏مَيْمُونٌ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبَّادٍ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تُؤْذُوا عِبَادَ اللَّهِ وَلَا تُعَيِّرُوهُمْ وَلَا تَطْلُبُوا عَوْرَاتِهِمْ فَإِنَّهُ مَنْ طَلَبَ عَوْرَةَ أَخِيهِ الْمُسْلِمِ طَلَبَ اللَّهُ عَوْرَتَهُ حَتَّى يَفْضَحَهُ فِي بَيْتِهِ ‏","","",""],[21369,21369,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَزَالُ طَائِفَةٌ مِنْ أُمَّتِي عَلَى الْحَقِّ ظَاهِرِينَ لَا يَضُرُّهُمْ مَنْ خَذَلَهُمْ حَتَّى يَأْتِيَ أَمْرُ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[21370,21370,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏لَا أَعْلَمُهُ إِلَّا قَدْ رَفَعَهُ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏رَفَعَهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عَائِدُ ‏ ‏الْمَرِيضِ فِي ‏ ‏مَخْرَفَةِ ‏ ‏الْجَنَّةِ ‏ ‏وَلَمْ يَشُكَّ فِيهِ ‏ ‏ابْنُ مَهْدِيٍّ ‏","","",""],[21371,21371,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُثْمَانَ ‏ ‏عَنِ ‏ ‏الْعَبَّاسِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ ‏ ‏حَدَّثَنِي ‏ ‏ثَوْبَانُ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ يَضْمَنُ لِي وَاحِدَةً وَأَضْمَنُ لَهُ الْجَنَّةَ قَالَ قُلْتُ أَنَا يَا رَسُولَ اللَّهِ قَالَ لَا تَسْأَلْ النَّاسَ شَيْئًا ‏ ‏قَالَ ‏ ‏فَكَانَ سَوْطُ ‏ ‏ثَوْبَانَ ‏ ‏سَقَطَ وَهُوَ عَلَى بَعِيرِهِ ‏ ‏فَيُنِيخُ ‏ ‏حَتَّى يَأْخُذَهُ وَمَا يَقُولُ لِأَحَدٍ نَاوِلْنِيهِ ‏","","",""],[21372,21372,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفْضَلُ دِينَارٍ يُنْفِقُهُ الرَّجُلُ عَلَى عِيَالِهِ ثُمَّ عَلَى نَفْسِهِ ثُمَّ فِي سَبِيلِ اللَّهِ ثُمَّ عَلَى أَصْحَابِهِ فِي سَبِيلِ اللَّهِ ‏ ‏قَالَ ‏ ‏أَبُو قِلَابَةَ ‏ ‏فَيَبْدَأُ بِالْعِيَالِ ‏ ‏و قَالَ ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏وَلَمْ يَرْفَعْهُ ‏ ‏دِينَارٌ أَنْفَقَهُ رَجُلٌ عَلَى دَابَّتِهِ فِي سَبِيلِ اللَّهِ ‏","","",""],[21373,21373,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ الْمُسْلِمَ إِذَا عَادَ أَخَاهُ الْمُسْلِمَ لَمْ يَزَلْ فِي ‏ ‏مَخْرَفَةِ ‏ ‏الْجَنَّةِ حَتَّى يَرْجِعَ ‏","","",""],[21374,21374,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ الطَّالَقَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏عَنِ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو عَمَّارٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو أَسْمَاءَ الرَّحَبِيُّ ‏ ‏حَدَّثَنِي ‏ ‏ثَوْبَانُ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَرَادَ أَنْ يَنْصَرِفَ مِنْ صَلَاتِهِ قَالَ ‏ ‏أَسْتَغْفِرُ اللَّهَ ثَلَاثًا ثُمَّ يَقُولُ اللَّهُمَّ أَنْتَ السَّلَامُ وَمِنْكَ السَّلَامُ ‏ ‏تَبَارَكْتَ ذَا الْجِلَالِ وَالْإِكْرَامِ ‏","","",""],[21375,21375,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏مَعْدَانَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَنَا ‏ ‏بِعُقْرِ ‏ ‏حَوْضِي يَوْمَ الْقِيَامَةِ أَذُودُ عَنْهُ النَّاسَ لِأَهْلِ ‏ ‏الْيَمَنِ ‏ ‏وَأَضْرِبُهُمْ بِعَصَايَ حَتَّى يَرْفَضَّ عَنْهُمْ قَالَ قِيلَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا سَعَتُهُ قَالَ مِنْ مَقَامِي إِلَى ‏ ‏عُمَانَ ‏ ‏يَغُتُّ ‏ ‏فِيهِ ‏ ‏مِيزَابَانِ ‏ ‏يَمُدَّانِهِ ‏","","",""],[21376,21376,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ الرَّحَبِيِّ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَرَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْبَقِيعِ ‏ ‏فِي ثَمَانِ عَشْرَةَ لَيْلَةً خَلَتْ مِنْ رَمَضَانَ بِرَجُلٍ ‏ ‏يَحْتَجِمُ ‏ ‏فَقَالَ ‏ ‏أَفْطَرَ ‏ ‏الْحَاجِمُ ‏ ‏وَالْمَحْجُومُ ‏","","",""],[21377,21377,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏حَدَّثَنِي ‏ ‏الْوَلِيدُ بْنُ هِشَامٍ ‏ ‏حَدَّثَنِي ‏ ‏مَعْدَانُ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِثَوْبَانَ مَوْلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدِّثْنَا حَدِيثًا يَنْفَعُنَا اللَّهُ بِهِ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا مِنْ عَبْدٍ يَسْجُدُ لِلَّهِ سَجْدَةً إِلَّا رَفَعَهُ اللَّهُ بِهَا دَرَجَةً وَحَطَّ عَنْهُ بِهَا خَطِيئَةً ‏","","",""],[21378,21378,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ الْحَارِثِ الذِّمَارِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ الرَّحَبِيِّ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ صَامَ رَمَضَانَ فَشَهْرٌ بِعَشَرَةِ أَشْهُرٍ وَصِيَامُ سِتَّةِ أَيَّامٍ بَعْدَ الْفِطْرِ فَذَلِكَ تَمَامُ صِيَامِ السَّنَةِ ‏","","",""],[21379,21379,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عِيسَى ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي الْجَعْدِ الْأَشْجَعِيِّ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَفَعَهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَرُدُّ الْقَدَرَ إِلَّا الدُّعَاءُ وَلَا يَزِيدُ فِي الْعُمُرِ إِلَّا الْبِرُّ وَإِنَّ الْعَبْدَ لَيُحْرَمُ الرِّزْقَ بِالذَّنْبِ يُصِيبُهُ ‏","","",""],[21380,21380,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَيَّاشٍ ‏ ‏وَعِصَامُ بْنُ خَالِدٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَرِيزُ بْنُ عُثْمَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مَيْسَرَةَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اسْتَقِيمُوا تُفْلِحُوا وَخَيْرُ أَعْمَالِكُمْ الصَّلَاةُ وَلَنْ يُحَافِظَ عَلَى الْوُضُوءِ إِلَّا مُؤْمِنٌ ‏ ‏وَقَالَ ‏ ‏عِصَامٌ ‏ ‏وَلَا يُحَافِظُ ‏","","",""],[21381,21381,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ صَالِحٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ شُرَيْحٍ الْحَضْرَمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي حَيٍّ الْمُؤَذِّنِ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا يَحِلُّ لَامْرِئٍ مِنْ الْمُسْلِمِينَ أَنْ يَنْظُرَ فِي ‏ ‏جَوْفِ ‏ ‏بَيْتِ امْرِئٍ حَتَّى يَسْتَأْذِنَ فَإِنْ نَظَرَ فَقَدْ دَخَلَ وَلَا يَؤُمَّ قَوْمًا فَيَخْتَصَّ نَفْسَهُ بِدُعَاءٍ دُونَهُمْ فَإِنْ فَعَلَ فَقَدْ خَانَهُمْ وَلَا يُصَلِّ وَهُوَ ‏ ‏حَقِنٌ ‏ ‏حَتَّى ‏ ‏يَتَخَفَّفَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْجَبَّارِ بْنُ مُحَمَّدٍ يَعْنِي الْخَطَّابِيَّ ‏ ‏حَدَّثَنَا ‏ ‏بَقِيَّةُ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ صَالِحٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ شُرَيْحٍ ‏ ‏فَذَكَرَ مَعْنَاهُ بِإِسْنَادِهِ ‏","","",""],[21382,21382,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ نَافِعٍ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عُبَيْدٍ الْكَلَاعِيِّ ‏ ‏عَنْ ‏ ‏زُهَيْرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لِكُلِّ سَهْوٍ سَجْدَتَانِ بَعْدَ مَا يُسَلِّمُ ‏","","",""],[21383,21383,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏ضَمْضَمِ بْنِ زُرْعَةَ ‏ ‏قَالَ ‏ ‏شُرَيْحُ بْنُ عُبَيْدٍ ‏ ‏مَرِضَ ‏ ‏ثَوْبَانُ ‏ ‏بِحِمْصَ ‏ ‏وَعَلَيْهَا ‏ ‏عَبْدُ اللَّهِ بْنُ قُرْطٍ الْأَزْدِيُّ ‏ ‏فَلَمْ يَعُدْهُ فَدَخَلَ عَلَى ‏ ‏ثَوْبَانَ ‏ ‏رَجُلٌ مِنْ ‏ ‏الْكَلَاعِيِّينَ ‏ ‏عَائِدًا فَقَالَ لَهُ ‏ ‏ثَوْبَانُ ‏ ‏أَتَكْتُبُ فَقَالَ نَعَمْ فَقَالَ اكْتُبْ فَكَتَبَ لِلْأَمِينِ ‏ ‏عَبْدِ اللَّهِ بْنِ قُرْطٍ ‏ ‏مِنْ ‏ ‏ثَوْبَانَ ‏ ‏مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَّا بَعْدُ فَإِنَّهُ لَوْ كَانَ ‏ ‏لِمُوسَى ‏ ‏وَعِيسَى ‏ ‏مَوْلًى بِحَضْرَتِكَ لَعُدْتَهُ ثُمَّ طَوَى الْكِتَابَ وَقَالَ لَهُ أَتُبَلِّغُهُ إِيَّاهُ فَقَالَ نَعَمْ فَانْطَلَقَ الرَّجُلُ بِكِتَابِهِ فَدَفَعَهُ إِلَى ‏ ‏ابْنِ قُرْطٍ ‏ ‏فَلَمَّا قَرَأَهُ قَامَ فَزِعًا فَقَالَ النَّاسُ مَا شَأْنُهُ أَحَدَثَ أَمْرٌ فَأَتَى ‏ ‏ثَوْبَانَ ‏ ‏حَتَّى دَخَلَ عَلَيْهِ ‏ ‏فَعَادَهُ ‏ ‏وَجَلَسَ عِنْدَهُ سَاعَةً ثُمَّ قَامَ فَأَخَذَ ‏ ‏ثَوْبَانُ ‏ ‏بِرِدَائِهِ وَقَالَ اجْلِسْ حَتَّى أُحَدِّثَكَ حَدِيثًا سَمِعْتُهُ ‏ ‏مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَمِعْتُهُ يَقُولُ ‏ ‏لَيَدْخُلَنَّ الْجَنَّةَ مِنْ أُمَّتِي سَبْعُونَ أَلْفًا لَا حِسَابَ عَلَيْهِمْ وَلَا عَذَابَ مَعَ كُلِّ أَلْفٍ سَبْعُونَ أَلْفًا ‏","","",""],[21384,21384,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ سَوَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏لَيْثٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏عُتْبَةَ أَبِي أُمَيَّةَ الدِّمَشْقِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَّامٍ الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏أَنَّهُ قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَوَضَّأَ وَمَسَحَ عَلَى الْخُفَّيْنِ وَعَلَى ‏ ‏الْخِمَارِ ‏ ‏ثُمَّ الْعِمَامَةِ ‏","","",""],[21385,21385,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ بْنِ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَبْدِ اللَّهِ بْنِ عُثْمَانَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏مَعْدَانَ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ سَأَلَ مَسْأَلَةً وَهُوَ عَنْهَا غَنِيٌّ كَانَتْ شَيْئًا فِي وَجْهِهِ يَوْمَ الْقِيَامَةِ ‏","","",""],[21386,21386,"","","‏ ‏حَدَّثَنَا ‏ ‏زَيْدُ بْنُ الْحُبَابِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ صَالِحٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو الزَّاهِرِيَّةِ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏ذَبَحَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُضْحِيَّةً لَهُ ثُمَّ قَالَ لِي يَا ‏ ‏ثَوْبَانُ ‏ ‏أَصْلِحْ لَحْمَ هَذِهِ الشَّاةِ قَالَ فَمَا زِلْتُ أُطْعِمُهُ مِنْهَا حَتَّى قَدِمَ ‏ ‏الْمَدِينَةَ ‏","","",""],[21387,21387,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏عَاصِمٌ يَعْنِي الْأَحْوَلَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ زَيْدٍ يَعْنِي أَبَا قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْأَشْعَثِ الصَّنْعَانِيِّ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ الرَّحَبِيِّ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ ‏ ‏عَادَ ‏ ‏مَرِيضًا لَمْ يَزَلْ فِي ‏ ‏خُرْفَةِ ‏ ‏الْجَنَّةِ فَقِيلَ يَا رَسُولَ اللَّهِ وَمَا ‏ ‏خُرْفَةُ ‏ ‏الْجَنَّةِ قَالَ ‏ ‏جَنَاهَا ‏","","",""],[21388,21388,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏وَأَبُو النَّضْرِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ يَتَقَبَّلُ لِي بِوَاحِدَةٍ أَتَقَبَّلُ لَهُ بِالْجَنَّةِ قَالَ قُلْتُ أَنَا يَا رَسُولَ اللَّهِ قَالَ لَا تَسْأَلْ النَّاسَ شَيْئًا ‏ ‏قَالَ ‏ ‏فَرُبَّمَا سَقَطَ سَوْطُ ‏ ‏ثَوْبَانَ ‏ ‏وَهُوَ عَلَى بَعِيرِهِ فَمَا يَسْأَلُ أَحَدًا أَنْ يُنَاوِلَهُ حَتَّى يَنْزِلَ إِلَيْهِ فَيَأْخُذَهُ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْعَبَّاسِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ مِينَاءَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ يَزِيدَ بْنِ مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ يَضْمَنُ لِي ‏ ‏خُلَّةً ‏ ‏وَأَضْمَنُ لَهُ الْجَنَّةَ فَذَكَرَ مَعْنَاهُ ‏","","",""],[21389,21389,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏مَرْزُوقٌ أَبُو عَبْدِ اللَّهِ الشَّامِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏رَجُلٌ مِنْ أَهْلِ ‏ ‏الشَّامِ ‏ ‏حَدَّثَنَا ‏ ‏ثَوْبَانُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَصَابَ أَحَدَكُمْ الْحُمَّى وَإِنَّ الْحُمَّى قِطْعَةٌ مِنْ النَّارِ فَلْيُطْفِئْهَا عَنْهُ بِالْمَاءِ الْبَارِدِ وَلْيَسْتَقْبِلْ نَهَرًا جَارِيًا يَسْتَقْبِلُ جِرْيَةَ الْمَاءِ فَيَقُولُ بِسْمِ اللَّهِ اللَّهُمَّ اشْفِ عَبْدَكَ وَصَدِّقْ رَسُولَكَ بَعْدَ صَلَاةِ الْفَجْرِ قَبْلَ طُلُوعِ الشَّمْسِ فَيَغْتَمِسُ فِيهِ ثَلَاثَ ‏ ‏غَمَسَاتٍ ثَلَاثَةَ أَيَّامٍ فَإِنْ لَمْ يَبْرَأْ فِي ثَلَاثٍ فَخَمْسٍ فَإِنْ لَمْ يَبْرَأْ فِي خَمْسٍ فَسَبْعٍ فَإِنْ لَمْ يَبْرَأْ فِي سَبْعٍ فَتِسْعٍ فَإِنَّهُ لَا يَكَادُ يُجَاوِزُ التِّسْعَ بِإِذْنِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[21390,21390,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏مَعْدَانَ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنِّي ‏ ‏لَبِعُقْرِ ‏ ‏حَوْضِي أَذُودُ عَنْهُ لِأَهْلِ ‏ ‏الْيَمَنِ ‏ ‏أَضْرِبُ بِعَصَايَ حَتَّى يَرْفَضَّ عَلَيْهِمْ فَسُئِلَ عَنْ عَرْضِهِ فَقَالَ مِنْ مُقَامِي إِلَى ‏ ‏عُمَانَ ‏ ‏وَسُئِلَ عَنْ شَرَابِهِ فَقَالَ أَشَدُّ بَيَاضًا مِنْ اللَّبَنِ وَأَحْلَى مِنْ الْعَسَلِ يَنْشَعِبُ فِيهِ ‏ ‏مِيزَابَانِ ‏ ‏يَمُدَّانِهِ ‏ ‏مِنْ الْجَنَّةِ أَحَدُهُمَا مِنْ ذَهَبٍ وَالْآخَرُ مِنْ وَرِقٍ ‏","","",""],[21391,21391,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏وَعَبْدُ الْوَهَّابِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏مَعْدَانَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ فَارَقَ الرُّوحُ الْجَسَدَ وَهُوَ بَرِيءٌ مِنْ ثَلَاثٍ دَخَلَ الْجَنَّةَ ‏ ‏الْكِبْرِ ‏ ‏وَالْغُلُولِ وَالدَّيْنِ ‏","","",""],[21392,21392,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏وَبَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏مَعْدَانَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ فَارَقَ الرُّوحُ الْجَسَدَ وَهُوَ بَرِيءٌ مِنْ ثَلَاثٍ دَخَلَ الْجَنَّةَ الْغُلُولِ وَالدَّيْنِ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏وَالْكِبْرِ ‏","","",""],[21393,21393,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَرَوْحٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏شَهْرِ بْنِ حَوْشَبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ غَنْمٍ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَفْطَرَ ‏ ‏الْحَاجِمُ ‏ ‏وَالْمَحْجُومُ ‏","","",""],[21394,21394,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏بُكَيْرُ بْنُ أَبِي السُّمَيْطِ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ الْغَطَفَانِيِّ ‏ ‏عَنْ ‏ ‏مَعْدَانَ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا عِنْدَ ‏ ‏عُقْرِ ‏ ‏حَوْضِي أَذُودُ النَّاسَ عَنْهُ لِأَهْلِ ‏ ‏الْيَمَنِ ‏ ‏إِنِّي لَأَضْرِبُهُمْ بِعَصَايَ حَتَّى يَرْفَضَّ عَلَيْهِمْ وَإِنَّهُ ‏ ‏لَيَغُتُّ ‏ ‏فِيهِ ‏ ‏مِيزَابَانِ ‏ ‏أَحَدُهُمَا مِنْ وَرِقٍ وَالْآخَرُ مِنْ ذَهَبٍ مَا بَيْنَ ‏ ‏بُصْرَى ‏ ‏وَصَنْعَاءَ ‏ ‏أَوْ مَا بَيْنَ ‏ ‏أَيْلَةَ ‏ ‏وَمَكَّةَ ‏ ‏أَوْ قَالَ مِنْ مُقَامِي هَذَا إِلَى ‏ ‏عُمَانَ ‏","","",""],[21395,21395,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وَرَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏مَكْحُولٌ ‏ ‏أَنَّ ‏ ‏شَيْخًا ‏ ‏مِنْ الْحَيِّ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏ثَوْبَانَ مَوْلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَفْطَرَ ‏ ‏الْحَاجِمُ ‏ ‏وَالْمَحْجُومُ ‏","","",""],[21396,21396,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏وَرَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ أَبِي عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي أَسْمَاءَ الرَّحَبِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ثَوْبَانُ مَوْلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَيْنَمَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْشِي فِي ‏ ‏الْبَقِيعِ ‏ ‏فِي رَمَضَانَ رَأَى رَجُلًا ‏ ‏يَحْتَجِمُ ‏ ‏فَقَالَ ‏ ‏أَفْطَرَ ‏ ‏الْحَاجِمُ ‏ ‏وَالْمَحْجُومُ ‏","","",""],[21397,21397,"","","‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ ثَوْبَانَ ‏ ‏حَدَّثَنِي ‏ ‏حَسَّانُ بْنُ عَطِيَّةَ ‏ ‏أَنَّ ‏ ‏أَبَا كَبْشَةَ السَّلُولِيَّ ‏ ‏حَدَّثَهُ أَنَّهُ سَمِعَ ‏ ‏ثَوْبَانَ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَدِّدُوا ‏ ‏وَقَارِبُوا وَاعْمَلُوا وَخَيِّرُوا وَاعْلَمُوا أَنَّ خَيْرَ أَعْمَالِكُمْ الصَّلَاةُ وَلَا يُحَافِظُ عَلَى الْوُضُوءِ إِلَّا مُؤْمِنٌ ‏","","",""],[21398,21398,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏وَأَبَانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏مَعْدَانَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ فَارَقَ الرُّوحُ الْجَسَدَ وَهُوَ بَرِيءٌ مِنْ ثَلَاثٍ دَخَلَ الْجَنَّةَ ‏ ‏الْكِبْرِ ‏ ‏وَالدَّيْنِ وَالْغُلُولِ ‏","","",""],[21399,21399,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَالِمٍ ‏ ‏عَنْ ‏ ‏مَعْدَانَ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ صَلَّى عَلَى جَنَازَةٍ فَلَهُ قِيرَاطٌ فَإِنْ شَهِدَ دَفْنَهَا فَلَهُ قِيرَاطَانِ الْقِيرَاطُ مِثْلُ ‏ ‏أُحُدٍ ‏","","",""],[21400,21400,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَيَعْلَى ‏ ‏قَالَا حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏ثَوْبَانَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَقِيمُوا وَلَنْ تُحْصُوا وَاعْلَمُوا أَنَّ خَيْرَ أَعْمَالِكُمْ الصَّلَاةُ وَلَا يُحَافِظُ عَلَى الْوُضُوءِ إِلَّا مُؤْمِنٌ ‏","","",""]];
